local BASE_TYPES = { str = true, flint = true, bool = true }

local function split_args(s)
  local out = {}
  local start = 1
  for i = 1, #s do
    if s:sub(i, i) == "," then
      out[#out + 1] = s:sub(start, i - 1)
      start = i + 1
    end
  end
  out[#out + 1] = s:sub(start)
  for i = 1, #out do
    out[i] = out[i]:gsub("^%s+", ""):gsub("%s+$", "")
  end
  return out
end

