c report_error(dict e, str src):", "    list lines = split_lines(src)", "    str ecat = \"SYNTAX_ERROR\"", "    if e.contains(\"cat\"):", "        ecat = e[cat]", "    flint line = 1", "    if e.contains(\"line\"):", "        line = e[line]", "    flint col = 1", "    if e.contains(\"col\"):", "        col = e[col]", "    str src_text = \"\"", "    if line >= 1 AND line <= len(lines):", "        src_text = lines[line - 1]", "", "    str red = \"\"", "    str yellow = \"\"", "    str reset = \"\"", "    if is_tty():", "        red = \"\\e[31m\"", "        yellow = \"\\e[33m\"", "        reset = \"\\e[0m\"", "", "    str num = cat([pad5(line), \" | \"])", "    list head = []", "    head.add(red)", "    head.add(ecat)", "    head.add(reset)", "    head.add(\": \")", "    head.add(e[path])", "    head.add(\":\")", "    head.add(str(line))", "    show_err({head.join(\"\")})", "    show_err({cat([num, src_text])})", "    str pad = spaces(len(num) + col - 1)", "    if e.contains(\"expected\"):", "        list body = []", "        body.add(pad)", "        body.add(\"^ \")", "        body.add(yellow)", "        body.add(\"expected \")", "        body.add(e[expected])", "        body.add(reset)", "        body.add(\", \")", "        body.add(red)", "        body.add(\"found \")", "        body.add(e[found])", "        body.add(reset)", "        show_err({body.join(\"\")})", "    else:", "        str msg = \"\"", "        if e.contains(\"msg\"):", "            msg = e[msg]", "        show_err({cat([pad, \"^ \", red, msg, reset])})", "", "# ---------- лексические таблицы ----------", "", "func is_digit(str c) -> bool:", "    return c != \"\" AND \"0123456789\".contains(c)", "", "func is_ascii_other(str c) -> bool:", "    str set = \" \\t\\r\\n#\\\"'\\{\\}()[]+-*/%<>=,:.;!?@$&|^~`\\\\\"", "    return set.contains(c)", "", "func is_name_char(str c) -> bool:", "    if c == \"\":", "        return FALSE", "    if is_digit(c):", "        return TRUE", "    if \"abcdefghijklmnopqrstu