й — шаблон.", "                    str tpl_raw = line[k + 1..r2[close]]", "                    if tpl_raw.contains(\"(\") AND char_at(line, r2[close] + 1) == \")\":", "                        # scan_parts останавливается на первой ')' — вложенные", "                        # вызовы надо досчитать самим, чтобы подсказка была", "                        # готовым кодом, который можно просто скопировать.", "                        flint dep = 0", "                        flint q = k + 1", "                        while q < len(line):", "                            str ch = line[q]", "                            if ch == \"(\":", "                                dep += 1", "                            elif ch == \")\":", "                                if dep == 0:", "                                    break", "                                dep -= 1", "                            q += 1", "                        str expr_raw = line[k + 1..q]", "                        str expr = expr_raw.trim()", "                        return {err: {line: lineno, col: k + 2, msg: cat([\"wrap the expression in '\\{\\}': \", word, \"(\\{\", expr, \"\\})\"])}}", "                    tokens.add({type: \"template\", parts: r2[parts], line: lineno, col: k + 2})", "                    tokens.add({type: \"op\", value: \")\", line: lineno, col: r2[close] + 1})", "                    i = r2[close] + 1", "                else:", "                    tokens.add({type: \"name\", value: word, line: lineno, col: col})", "                    i = j2", "            elif is_keyword(word):", "                tokens.add({type: \"kw\", value: word, line: lineno, col: col})", "                i = j2", "            else:", "                tokens.add({type: \"name\", value: word, line: lineno, col: col})", "                i = j2", "        else:", "            str three = line[i..i + 3]", "            str two = line[i..i + 2]", "            if is_op3(three):", "                tokens.add({type: \"op\", value: three, line: lineno, col: i + 1})", "                i += 3", "            elif is_op2(two):", "                tokens.add({type: \"op\", value: two, line: lineno, col: i + 1})", "                i += 2", "            elif is_op1(c):", "                tokens.add({type: \"op\", value: c, line: lineno, col: i + 1})", "                i += 1", "            else:", "                return {err: {msg: cat([\"unexpected character '\", c, \"'\"]), line: lineno, col: i + 1}}", "    return {err: NONE}", "", "# Токенизирует весь файл. Возвращает {tokens, err}.", "func lex(str src, str path) -> dict:", "    list tokens = []", "    list indent_stack = [\"\"]", "    flint lineno = 0", "    bool in_block = FALSE", "    list lines = split_lines(src)", "", "    for raw_line in lines:", "        str line = raw_line", "        lineno += 1", "        str trimmed = line.trim()", "", "        bool skip = FALSE", "        if in_block:", "            if trimmed[..3] == \"---\":", "                in_block = FALSE", "            skip = TRUE", "        elif trimmed[..3] == \"---\":", "            in_block = TRUE", "            skip = TRUE", "        elif trimmed == \"\" OR trimmed[..1] == \"#\":", "            skip = TRUE", "        if NOT skip:", "            flint k = 0", "            flint ln = len(line)", "            while k < ln AND (line[k] == \" \" OR line[k] == \"\\t\"):", "                k += 1", "            str indent = line[..k]", "            if indent.contains(\" \") AND indent.contains(\"\\t\"):", "                return {tokens: tokens, err: {msg: \"mixed tabs and spaces in indentation\", line: lineno, col: 1}}", "", "            str top = indent_stack[len(indent_stack) - 1]", "            if indent != top:", "                if indent[..len(top)] == top:", "                    indent_stack.add(indent)", "                    tokens.add({type: \"indent\", line: lineno, col: 1})", "                else:", "                    while len(indent_stack) > 1 AND indent_stack[len(indent_stack) - 1] != indent:", "                        indent_stack.del(len(indent_stack) - 1)", "                        tokens.add({type: \"dedent\", line: lineno, col: 1})", "                    if indent_stack[len(indent_stack) - 1] != indent:", "                        return {tokens: tokens, err: {msg: \"inconsistent indentation\", line: lineno, col: 1}}", "", "            dict r = scan_line(line, len(indent), lineno, tokens)", "            if NOT (r[err] is NONE):", "                return {tokens: tokens, err: r[err]}", "            tokens.add({type: \"newline\", line: lineno, col: len(line) + 1})", "", "    while len(indent_stack) > 1:", "        indent_stack.del(len(indent_stack) - 1)", "        tokens.add({type: \"dedent\", line: lineno, col: 1})", "    tokens.add({type: \"eof\", line: lineno, col: 1})", "    return {tokens: tokens, err: NONE}", "", "# ---------- отладка: --tokens ----------", "", "func describe_tok(dict t) -> str:", "    list p = []", "    p.add(t[type])", "    p.add(\" \")", "    p.add(str(t[line]))", "    p.add(\":\")", "    p.add(str(t[col]))", "    if t.contains(\"value\"):", "        p.add(\" \")", "        p.add(str(t[value]))", "    if t.contains(\"raw\"):", "        p.add(\" raw=\")", "        p.add(t[raw])", "    if t.contains(\"parts\"):", "        p.add(\" parts=\")", "        p.add(str(t[parts]))", "    return p.join(\"\")", "", "func dump_tokens(list toks):", "    for t in toks:", "        show({describe_tok(t)})", "", "# ---------- парсер: состояние и токены ----------", "", "func token_at(dict st, flint i) -> dict:", "    list ts = st[toks]", "    if len(ts) == 0:", "        return {type: \"eof\", line: 1, col: 1}", "    if i < 0 OR i >= len(ts):", "        return ts[len(ts) - 1]", "    return ts[i]", "", "func tk(dict st) -> dict:", "    return token_at(st, st[pos])", "", "func advance(dict st) -> dict:", "    dict t = tk(st)", "    st.add(\"pos\", st[pos] + 1)", "    return t", "", "func tok_is(dict t, str ty, str val) -> bool:", "    if t[type] != ty:", "        return FALSE", "    if val == \"\":", "        return TRUE", "    return t[value] == val", "", "func peek_value(dict st) -> str:", "    dict n = token_at(st, st[pos] + 1)", "    if n[type] == \"op\":", "        return n[value]", "    return \"\"", "", "func fail(dict st, dict t, str ecat, str expected, str found):", "    if NOT (st[err] is NONE):", "        return:", "    dict e = {cat: ecat, line: 1, col: 1, expected: expected, found: found, path: st[path]}", "    if len(t) > 0:", "        e.add(\"line\", t[line])", "        e.add(\"col\", t[col])", "    st.add(\"err\", e)", "", "func expect_tok(dict st, str ty, str val, str what) -> dict:", "    dict t = tk(st)", "    if NOT tok_is(t, ty, val):", "        fail(st, t, \"SYNTAX_ERROR\", what, describe_tok(t))", "        return {type: \"eof\", value: \"\", line: 1, col: 1}", "    advance(st)", "    return t", "", "# ---------- парсер: типы и имена ----------", "", "func is_type_keyword(str w) -> bool:", "    if w == \"str\" OR w == \"flint\" OR w == \"bool\":", "        return TRUE", "    if w == \"list\" OR w == \"dict\" OR w == \"froz\":", "        return TRUE", "    return FALSE", "", "func is_base_type(str w) -> bool:", "    return w == \"str\" OR w == \"flint\" OR w == \"bool\"", "", "# Имя типа без параметров: \"list[flint,str]\" -> \"list\".", "func base_type(str t) -> str:", "    flint i = 0", "    while i < len(t):", "        if t[i] == \"[\":", "            return t[..i]", "        i += 1", "    return t", "", "func is_typed_spec(str t) -> bool:", "    return t.contains(\"[\")", "", "# Список аргументов без пробелов: \"dict[str,flint]\" -> [\"str\", \"flint\"].", "func type_args(str t) -> list:", "    list out = []", "    flint i = 0", "    while i < len(t):", "        if t[i] == \"[\":", "            str inner = t[i + 1..len(t) - 1]", "            flint start = 0", "            flint j = 0", "            while j <= len(inner):", "                if j == len(inner) OR inner[j] == \",\":", "                    out.add(inner[start..j])", "                    start = j + 1", "                j += 1", "            break", "        i += 1", "    return out", "", "# str / flint / bool / list[T,...] / froz[T,...] / dict[K,V].", "func parse_type_spec(dict st) -> str:", "    dict t = tk(st)", "    if t[type] != \"kw\":", "        fail(st, t, \"TYPE_ERROR\", \"type name\", describe_tok(t))", "        return \"\"", "    str base = t[value]", "    if NOT is_type_keyword(base) OR base == \"NONE\":", "        fail(st, t, \"TYPE_ERROR\", \"type name\", describe_tok(t))", "        return \"\"", "    advance(st)", "    if is_base_type(base) OR NOT tok_is(tk(st), \"op\", \"[\"):", "        return base", "    expect_tok(st, \"op\", \"[\", \"'['\")", "    if NOT (st[err] is NONE):", "        return \"\"", "    list targs = []", "    while TRUE:", "        dict at = tk(st)", "        if at[type] != \"kw\" OR NOT is_base_type(at[value]):", "            fail(st, at, \"TYPE_ERROR\", \"str, flint or bool\", describe_tok(at))", "            return \"\"", "        str av = at[value]", "        advance(st)", "        targs.add(av)", "        if tok_is(tk(st), \"op\", \",\") OR (base == \"dict\" AND tok_is(tk(st), \"op\", \"|\")):", "            advance(st)", "        else:", "            break", "    expect_tok(st, \"op\", \"]\", \"']'\")", "    if NOT (st[err] is NONE):", "        return \"\"", "    if base == \"dict\":", "        if len(targs) != 2:", "            fail(st, t, \"TYPE_ERROR\", \"dict[key type,value type]\", \"wrong number of type arguments\")", "            return \"\"", "        if targs[0] != \"str\":", "            fail(st, t, \"TYPE_ERROR\", \"str dict key\", targs[0])", "            return \"\"", "    return cat([base, \"[\", targs.join(\",\"), \"]\"])", "", "func is_numeric(str t) -> bool:", "    return t == \"flint\" OR t == \"NONE\" OR t == \"any\"", "", "func assignable(str from, str to) -> bool:", "    return from == \"NONE\" OR from == \"any\" OR from == to", "", "func is_compare(str op) -> bool:", "    return op == \"==\" OR op == \"!=\" OR op == \"<\" OR op == \"<=\" OR op == \">\" OR op == \">=\"", "", "func is_compound(str op) -> bool:", "    if op == \"+=\" OR op == \"-=\" OR op == \"*=\" OR op == \"/=\":", "        return TRUE", "    return op == \"%=\" OR op == \"//=\" OR op == \"**=\"", "", "func is_const_name(str n) -> bool:", "    if len(n) == 0:", "        return FALSE", "    flint i = 0", "    while i < len(n):", "        str c = n[i]", "        if NOT \"ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_\".contains(c):", "            return FALSE", "        i += 1", "    return TRUE", "", "func builtin_arg_ok(str spec, str t) -> bool:", "    if spec == \"any\":", "        return TRUE", "    if t == \"NONE\" OR t == \"any\":", "        return TRUE", "    if t == spec:", "        return TRUE", "    str b = base_type(t)", "    if spec == \"strlistdict\":", "        return b == \"str\" OR b == \"list\" OR b == \"froz\" OR b == \"dict\"", "    if spec == \"listdict\":", "        return b == \"list\" OR b == \"froz\" OR b == \"dict\"", "    return b == spec", "", "func builtin_arg_desc(str spec) -> str:", "    if spec == \"any\":", "        return \"any value\"", "    if spec == \"strlistdict\":", "        return \"str, list, froz, dict\"", "    if spec == \"listdict\":", "        return \"list, froz, dict\"", "    return spec", "", "func builtin_info(str name) -> dict:", "    if name == \"len\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"strlistdict\"}", "    if name == \"type\":", "        return {ok: TRUE, n: 1, ret: \"str\", a1: \"any\"}", "    if name == \"str\":", "        return {ok: TRUE, n: 1, ret: \"str\", a1: \"any\"}", "    if name == \"flint\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"any\"}", "    if name == \"up\":", "        return {ok: TRUE, n: 1, ret: \"str\", a1: \"str\"}", "    if name == \"low\":", "        return {ok: TRUE, n: 1, ret: \"str\", a1: \"str\"}", "    if name == \"title\":", "        return {ok: TRUE, n: 1, ret: \"str\", a1: \"str\"}", "    if name == \"abs\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"flint\"}", "    if name == \"round\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"flint\"}", "    if name == \"floor\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"flint\"}", "    if name == \"ceil\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"flint\"}", "    if name == \"sqrt\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"flint\"}", "    if name == \"min\":", "        return {ok: TRUE, variadic: TRUE, min: 1, max: 9, ret: \"flint\", a1: \"flint\"}", "    if name == \"max\":", "        return {ok: TRUE, variadic: TRUE, min: 1, max: 9, ret: \"flint\", a1: \"flint\"}", "    if name == \"sum\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"list\"}", "    if name == \"avg\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"list\"}", "    if name == \"keys\":", "        return {ok: TRUE, n: 1, ret: \"list\", a1: \"dict\"}", "    if name == \"values\":", "        return {ok: TRUE, n: 1, ret: \"list\", a1: \"dict\"}", "    if name == \"upk\":", "        return {ok: TRUE, n: 1, ret: \"str\", a1: \"listdict\"}", "    if name == \"sort\":", "        return {ok: TRUE, n: 1, ret: \"list\", a1: \"list\"}", "    if name == \"reverse\":", "        return {ok: TRUE, n: 1, ret: \"list\", a1: \"list\"}", "    if name == \"clear\":", "        return {ok: TRUE, n: 1, ret: \"NONE\", a1: \"listdict\"}", "    if name == \"map\":", "        return {ok: TRUE, n: 2, ret: \"list\", a1: \"list\", a2: \"func\"}", "    if name == \"filter\":", "        return {ok: TRUE, n: 2, ret: \"list\", a1: \"list\", a2: \"func\"}", "    if name == \"reduce\":", "        return {ok: TRUE, n: 3, ret: \"any\", a1: \"list\", a2: \"func\", a3: \"any\"}", "    if name == \"system\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"str\"}", "    if name == \"assert\":", "        return {ok: TRUE, n: 2, ret: \"NONE\", a1: \"any\", a2: \"str\"}", "    if name == \"expect\":", "        return {ok: TRUE, n: 1, ret: \"expect\", a1: \"any\"}", "    if name == \"read_file\":", "        return {ok: TRUE, n: 1, ret: \"str\", a1: \"str\"}", "    if name == \"write_file\":", "        return {ok: TRUE, n: 2, ret: \"bool\", a1: \"str\", a2: \"str\"}", "    if name == \"file_exists\":", "        return {ok: TRUE, n: 1, ret: \"bool\", a1: \"str\"}", "    if name == \"args\":", "        return {ok: TRUE, n: 0, ret: \"list\", a1: \"any\"}", "    if name == \"exit\":", "        return {ok: TRUE, n: 1, ret: \"NONE\", a1: \"flint\"}", "    if name == \"time_ms\":", "        return {ok: TRUE, n: 0, ret: \"flint\", a1: \"any\"}", "    if name == \"is_tty\":", "        return {ok: TRUE, n: 0, ret: \"bool\", a1: \"any\"}", "    return {ok: FALSE}", "", "func is_builtin(str name) -> bool:", "    return builtin_info(name)[ok]", "", "func method_info(str base, str name) -> dict:", "    str b = base_type(base)", "    if b == \"str\":", "        if name == \"part\":", "            return {ok: TRUE, min: 0, max: 2, a1: \"str\", a2: \"flint\", rt: \"str_part\", ret: \"list\", nullable: FALSE}", "        if name == \"find\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"str_find\", ret: \"flint\", nullable: TRUE}", "        if name == \"contains\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"str_contains\", ret: \"bool\", nullable: FALSE}", "        if name == \"preff\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"str_preff\", ret: \"bool\", nullable: FALSE}", "        if name == \"suff\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"str_suff\", ret: \"bool\", nullable: FALSE}", "        if name == \"trim\":", "            return {ok: TRUE, min: 0, max: 1, a1: \"str\", a2: \"any\", rt: \"str_trim\", ret: \"str\", nullable: FALSE}", "        if name == \"triml\":", "            return {ok: TRUE, min: 0, max: 1, a1: \"str\", a2: \"any\", rt: \"str_triml\", ret: \"str\", nullable: FALSE}", "        if name == \"trimr\":", "            return {ok: TRUE, min: 0, max: 1, a1: \"str\", a2: \"any\", rt: \"str_trimr\", ret: \"str\", nullable: FALSE}", "        if name == \"remove\":", "            return {ok: TRUE, min: 1, max: 2, a1: \"str\", a2: \"flint\", rt: \"str_remove\", ret: \"str\", nullable: FALSE}", "        if name == \"replace\":", "            return {ok: TRUE, min: 2, max: 2, a1: \"str\", a2: \"str\", rt: \"str_replace\", ret: \"str\", nullable: FALSE}", "        if name == \"count\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"str_count\", ret: \"flint\", nullable: FALSE}", "    elif b == \"list\" OR b == \"froz\":", "        if b == \"froz\" AND (name == \"add\" OR name == \"del\" OR name == \"remove\" OR name == \"replace\" OR name == \"replace_value\"):", "            return {ok: FALSE}", "        if name == \"add\":", "            return {ok: TRUE, min: 1, max: 2, a1: \"any\", a2: \"any\", rt: \"list_add\", ret: \"NONE\", nullable: FALSE}", "        if name == \"del\":", "            return {ok: TRUE, min: 0, max: 1, a1: \"flint\", a2: \"any\", rt: \"list_del\", ret: \"NONE\", nullable: FALSE}", "        if name == \"remove\":", "            return {ok: TRUE, min: 1, max: 2, a1: \"any\", a2: \"flint\", rt: \"list_remove\", ret: \"bool\", nullable: FALSE}", "        if name == \"replace\":", "            return {ok: TRUE, min: 2, max: 2, a1: \"flint\", a2: \"any\", rt: \"list_replace\", ret: \"NONE\", nullable: FALSE}", "        if name == \"replace_value\":", "            return {ok: TRUE, min: 2, max: 2, a1: \"any\", a2: \"any\", rt: \"list_replace_value\", ret: \"bool\", nullable: FALSE}", "        if name == \"contains\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"any\", a2: \"any\", rt: \"list_contains\", ret: \"bool\", nullable: FALSE}", "        if name == \"count\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"any\", a2: \"any\", rt: \"list_count\", ret: \"flint\", nullable: FALSE}", "        if name == \"index\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"any\", a2: \"any\", rt: \"list_index_of\", ret: \"flint\", nullable: TRUE}", "        if name == \"join\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"list_join\", ret: \"str\", nullable: FALSE}", "    elif b == \"dict\":", "        if name == \"add\":", "            return {ok: TRUE, min: 2, max: 2, a1: \"str\", a2: \"any\", rt: \"dict_add\", ret: \"NONE\", nullable: FALSE}", "        if name == \"take\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"dict_take\", ret: \"any\", nullable: TRUE}", "        if name == \"remove\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"dict_remove\", ret: \"bool\", nullable: FALSE}", "        if name == \"contains\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"dict_contains\", ret: \"bool\", nullable: FALSE}", "        if name == \"merge\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"dict\", a2: \"any\", rt: \"dict_merge\", ret: \"dict\", nullable: FALSE}", "    elif b == \"expect\":", "        if name == \"equals\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"any\", a2: \"any\", rt: \"expect_equals\", ret: \"NONE\", nullable: FALSE}", "        if name == \"is_true\":", "            return {ok: TRUE, min: 0, max: 0, a1: \"any\", a2: \"any\", rt: \"expect_true\", ret: \"NONE\", nullable: FALSE}", "        if name == \"is_false\":", "            return {ok: TRUE, min: 0, max: 0, a1: \"any\", a2: \"any\", rt: \"expect_false\", ret: \"NONE\", nullable: FALSE}", "        if name == \"is_none\":", "            return {ok: TRUE, min: 0, max: 0, a1: \"any\", a2: \"any\", rt: \"expect_none\", ret: \"NONE\", nullable: FALSE}", "        if name == \"contains\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"any\", a2: \"any\", rt: \"expect_contains\", ret: \"NONE\", nullable: FALSE}", "    return {ok: FALSE}", "", "func is_reserved(str name) -> bool:", "    if is_builtin(name) OR name == \"show\" OR name == \"show_err\" OR name == \"input\" OR name == \"Error\":", "        return TRUE", "    if name == \"error\" OR name == \"ANY_ERROR\":", "        return TRUE", "    # Методы типов — тоже занятые имена: `add`, `take`, `contains`, `text` и т.д.", "    return method_info(\"str\", name)[ok] OR method_info(\"list\", name)[ok] OR method_info(\"dict\", name)[ok] OR method_info(\"expect\", name)[ok] OR name == \"text\"", "", "# Встроенная модель Error: схема известна компилятору, объект создаёт рантайм.", "func error_schema() -> dict:", "    dict fields = {cat: \"str\", msg: \"str\", file: \"str\", line: \"flint\", col: \"flint\"}", "    dict consts = {}", "    consts.add(\"cat\", TRUE)", "    consts.add(\"msg\", TRUE)", "    consts.add(\"file\", TRUE)", "    consts.add(\"line\", TRUE)", "    consts.add(\"col\", TRUE)", "    dict meth = {}", "    meth.add(\"text\", {params: [], ret: \"str\", ret_nullable: FALSE, line: 1, col: 1})", "    return {name: \"Error\", model_fields: {}, field_types: fields, consts: consts, init_fields: {}, params: [], param_types: {}, methods: meth, method_order: [\"text\"], ctor: NONE, order: [], field_order: []}", "", "# Категории, которые рантайм может положить в error.cat.", "func is_error_category(str c) -> bool:", "    if c == \"ANY_ERROR\" OR c == \"ARGCOUNT_ERROR\" OR c == \"ASSERT_ERROR\":", "        return TRUE", "    if c == \"CONST_ERROR\" OR c == \"EXPECT_ERROR\" OR c == \"FILE_ERROR\":", "        return TRUE", "    if c == \"NAME_ERROR\" OR c == \"RUNTIME_ERROR\" OR c == \"TYPE_ERROR\":", "        return TRUE", "    if c == \"TYPE_MISMATCH_ERROR\" OR c == \"VALUE_ERROR\":", "        return TRUE", "    if c == \"PANIC_ERROR\":", "        return TRUE", "    return FALSE", "", "func is_scalar_type(str t) -> bool:", "    return t == \"str\" OR t == \"flint\" OR t == \"bool\"", "", "func is_model_type(dict st, str t) -> bool:", "    dict ms = st[models]", "    return ms.contains(t)", "", "func model_schema(dict st, str t) -> dict:", "    dict ms = st[models]", "    return ms.take(t)", "", "func check_field_name(dict st, dict tok, str nm):", "    if is_reserved(nm):", "        fail(st, tok, \"NAME_ERROR\", \"free field name\", cat([\"reserved '\", nm, \"'\"]))", "        return:", "", "# Регистрирует экземплярное поле в схеме. new=FALSE — поле уже было.", "func add_model_field(dict st, dict m, dict tok, str nm, str fty, bool computed):", "    dict mf = m[model_fields]", "    dict ft = m[field_types]", "    dict cs = m[consts]", "    dict initf = m[init_fields]", "    dict methods = m[methods]", "    if mf.contains(nm) OR ft.contains(nm) OR methods.contains(nm):", "        fail(st, tok, \"REDECLARE_ERROR\", \"unique field/method name\", cat([\"name '\", nm, \"' is already declared\"]))", "        return:", "    ft.add(nm, fty)", "    list fo = m[field_order]", "    fo.add(nm)", "    if is_const_name(nm):", "        cs.add(nm, TRUE)", "    if computed AND NOT is_const_name(nm):", "        initf.add(nm, TRUE)", "", "func parse_type_name(dict st) -> str:", "    dict t = tk(st)", "    if t[type] == \"name\" AND is_model_type(st, t[value]):", "        advance(st)", "        return t[value]", "    if tok_is(t, \"kw\", \"NONE\"):", "        advance(st)", "        return \"NONE\"", "    return parse_type_spec(st)", "", "# Обычная строка без интерполяции: для ключей dict и сообщения panic.", "func plain_string_of(dict st, dict t) -> str:", "    list parts = t[parts]", "    list buf = []", "    for p0 in parts:", "        dict p = p0", "        if p[kind] != \"text\":", "            fail(st, t, \"TYPE_ERROR\", \"plain string\", \"interpolated string\")", "            return \"\"", "        buf.add(p[value])", "    return buf.join(\"\")", "", "# Соответствует ли литерал параметризованному типу.", "func literal_ok(dict st, dict e, str spec) -> bool:", "    str base = base_type(spec)", "    list targs = type_args(spec)", "    if base == \"list\" OR base == \"froz\":", "        if e[k] != \"list\":", "            return FALSE", "        list its = e[items]", "        for it0 in its:", "            dict it = it0", "            bool ok = FALSE", "            for a0 in targs:", "                str want = a0", "                if it[t] == want:", "                    ok = TRUE", "            if NOT ok:", "                return FALSE", "        return TRUE", "    if base == \"dict\":", "        if e[k] != \"dict\":", "            return FALSE", "        list prs = e[pairs]", "        for pd0 in prs:", "            dict pd = pd0", "            dict pv = pd[value]", "            if pv[t] != targs[1]:", "                return FALSE", "        return TRUE", "    return FALSE", "", "# В новой модели условием может быть только bool (и NONE как ложь).", "func check_condition(dict st, dict e, dict tok):", "    str et = base_type(e[t])", "    if et != \"bool\" AND et != \"NONE\" AND et != \"any\":", "        fail(st, tok, \"TYPE_ERROR\", \"bool condition (TRUE, FALSE or NONE)\", e[t])", "", "# Prelude объявляет функции для проверки типов до разбора пользовательского кода.", "func add_prelude_func(dict st, str name, str lua, list ptypes, str ret):", "    list params = []", "    for pt0 in ptypes:", "        str pt = pt0", "        params.add({name: \"arg\", type: pt, line: 1, col: 1})", "    dict info = {params: params, ret: ret, ret_nullable: FALSE, inferring: FALSE}", "    dict funcs = st[funcs]", "    funcs.add(name, info)", "    dict fnames = st[fnames]", "    fnames.add(name, lua)", "", "func add_prelude(dict st):", "    add_prelude_func(st, \"prelude_cat\", \"prelude_f_1\", [\"str\"], \"str\")", "    add_prelude_func(st, \"path_join\", \"prelude_f_2\", [\"str\", \"str\"], \"str\")", "    add_prelude_func(st, \"now_ms\", \"prelude_f_3\", [], \"flint\")", "    add_prelude_func(st, \"parse_args\", \"prelude_f_4\", [], \"dict\")", "    add_prelude_func(st, \"parse_csv\", \"prelude_f_5\", [\"str\"], \"list\")", "    add_prelude_func(st, \"parse_json\", \"prelude_f_6\", [\"str\"], \"dict\")", "", "func mangle_var(dict st, str name) -> str:", "    st.add(\"vcounter\", st[vcounter] + 1)", "    str lua = cat([\"v_\", str(st[vcounter])])", "    dict names = st[names]", "    names.add(name, lua)", "    return lua", "", "func mangle_func(dict st, str name) -> str:", "    st.add(\"fcounter\", st[fcounter] + 1)", "    str lua = cat([\"f_\", str(st[fcounter])])", "    dict fnames = st[fnames]", "    fnames.add(name, lua)", "    return lua", "", "func e_nullable(dict e) -> bool:", "    if e.contains(\"nullable\"):", "        return e[nullable]", "    return FALSE", "", "# ---------- парсер: выражения ----------", "", "func shift_token_pos(dict t, flint dl, flint dc) -> bool:", "    if NOT t.contains(\"line\"):", "        return TRUE", "    flint old = t[line]", "    t.add(\"line\", old + dl)", "    if old == 1:", "        t.add(\"col\", t[col] + dc)", "    if t.contains(\"parts\"):", "        list ps = t[parts]", "        flint pi = 0", "        while pi < len(ps):", "            shift_token_pos(ps[pi], dl, dc)", "            pi += 1", "    return TRUE", "", "func template_state(dict st, dict p) -> dict:", "    dict lx = lex(p[src], st[path])", "    list ts = lx[tokens]", "    dict e0 = NONE", "    if NOT (lx[err] is NONE):", "        dict le = lx[err]", "        flint eline = p[line] + le[line] - 1", "        flint ecol = le[col]", "        if le[line] == 1:", "            ecol = p[col] + le[col] - 1", "        e0 = {cat: \"SYNTAX_ERROR\", line: eline, col: ecol, msg: le[msg], path: st[path]}", "    flint i = 0", "    while i < len(ts):", "        dict t2 = ts[i]", "        shift_token_pos(t2, p[line] - 1, p[col] - 1)", "        i += 1", "    return {toks: ts, pos: 0, path: st[path], vars: st[vars], nullable: st[nullable], maybe_unset: st[maybe_unset], gvars: st[gvars], gnullable: st[gnullable], gmaybe: st[gmaybe], for_names: st[for_names], funcs: st[funcs], in_func: st[in_func], func_ret: st[func_ret], func_returns: st[func_returns], block_depth: st[block_depth], loop_depth: st[loop_depth], cond_depth: st[cond_depth], err: e0, names: st[names], fnames: st[fnames], vcounter: st[vcounter], fcounter: st[fcounter], models: st[models], model_ctx: st[model_ctx]}", "", "func parse_expr(dict st, flint min_bp) -> dict:", "    if NOT (st[err] is NONE):", "        return {}", "    dict t = tk(st)", "    str ty = t[type]", "    dict e = {}", "    dict ptok = NONE", "    str pfn = \"\"", "", "    if ty == \"number\":", "        advance(st)", "        e = {k: \"num\", value: t[value], t: \"flint\", line: t[line], col: t[col]}", "    elif ty == \"string\":", "        advance(st)", "        ptok = t", "    elif ty == \"kw\" AND t[value] == \"TRUE\":", "        advance(st)", "        e = {k: \"bool\", value: TRUE, t: \"bool\", line: t[line], col: t[col]}", "    elif ty == \"kw\" AND t[value] == \"FALSE\":", "        advance(st)", "        e = {k: \"bool\", value: FALSE, t: \"bool\", line: t[line], col: t[col]}", "    elif ty == \"kw\" AND t[value] == \"NONE\":", "        advance(st)", "        e = {k: \"none\", t: \"NONE\", line: t[line], col: t[col]}", "    elif ty == \"kw\" AND t[value] == \"self\":", "        dict mctx = st[model_ctx]", "        if mctx is NONE:", "            fail(st, t, \"SCOPE_ERROR\", \"'self' inside a model\", \"'self' outside a model\")", "            return {}", "        advance(st)", "        if tok_is(tk(st), \"op\", \"(\"):", "            advance(st)", "            list snames = []", "            if NOT tok_is(tk(st), \"op\", \")\"):", "                while TRUE:", "                    dict snt = expect_tok(st, \"name\", \"\", \"parameter name in self(...)\")", "                    if NOT (st[err] is NONE):", "                        return {}", "                    snames.add(snt)", "                    if tok_is(tk(st), \"op\", \",\"):", "                        advance(st)", "                    else:", "                        break", "            expect_tok(st, \"op\", \")\", \"')'\")", "            if NOT (st[err] is NONE):", "                return {}", "            e = {k: \"self_init\", names: snames, t: \"NONE\", line: t[line], col: t[col]}", "        else:", "            e = {k: \"var\", name: \"self\", lua: \"self\", t: mctx[model_name], line: t[line], col: t[col]}", "    elif ty == \"name\" AND is_model_type(st, t[value]) AND peek_value(st) == \"(\":", "        str cmn = t[value]", "        dict cms = model_schema(st, cmn)", "        dict ccons = cms[ctor]", "        if ccons is NONE:", "            fail(st, t, \"NAME_ERROR\", cat([\"declared construct of '\", cmn, \"'\"]), \"model without construct\")", "            return {}", "        advance(st)", "        expect_tok(st, \"op\", \"(\", \"'('\")", "        list cmargs = []", "        if NOT tok_is(tk(st), \"op\", \")\"):", "            while TRUE:", "                dict cma = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return {}", "                cmargs.add(cma)", "                if tok_is(tk(st), \"op\", \",\"):", "                    advance(st)", "                else:", "                    break", "        expect_tok(st, \"op\", \")\", \"')'\")", "        if NOT (st[err] is NONE):", "            return {}", "        list cmparams = ccons[params]", "        if len(cmargs) != len(cmparams):", "            fail(st, t, \"ARGCOUNT_ERROR\", cat([str(len(cmparams)), \" argument(s) to '\", cmn, \"'\"]), cat([str(len(cmargs)), \" argument(s)\"]))", "            return {}", "        list cmpt = []", "        flint cmi = 0", "        while cmi < len(cmargs):", "            dict cma2 = cmargs[cmi]", "            dict cmp = cmparams[cmi]", "            cmpt.add(cmp[type])", "            if NOT assignable(cma2[t], cmp[type]):", "                fail(st, {line: cma2[line], col: cma2[col]}, \"TYPE_ERROR\", cat([\"argument \", str(cmi + 1), \" of '\", cmn, \"' to be \", cmp[type]]), cma2[t])", "                return {}", "            cmi += 1", "        e = {k: \"model_new\", mname: cmn, args: cmargs, ptypes: cmpt, t: cmn, line: t[line], col: t[col]}", "    elif (ty == \"kw\" OR ty == \"name\") AND is_builtin(t[value]) AND peek_value(st) == \"(\":", "        str bn = t[value]", "        advance(st)", "        expect_tok(st, \"op\", \"(\", \"'('\")", "        list bargs = []", "        if bn == \"map\" OR bn == \"filter\" OR bn == \"reduce\":", "            dict hcoll = parse_expr(st, 0)", "            if NOT (st[err] is NONE):", "                return {}", "            bargs.add(hcoll)", "            expect_tok(st, \"op\", \",\", \"','\")", "            if NOT (st[err] is NONE):", "                return {}", "            dict hft = expect_tok(st, \"name\", \"\", \"function name\")", "            if NOT (st[err] is NONE):", "                return {}", "            str hfn = hft[value]", "            dict hfuncs = st[funcs]", "            if NOT hfuncs.contains(hfn):", "                fail(st, hft, \"NAME_ERROR\", \"declared function\", cat([\"undeclared function '\", hfn, \"'\"]))", "                return {}", "            dict hfi = hfuncs.take(hfn)", "            flint hwant = 1", "            if bn == \"reduce\":", "                hwant = 2", "            if len(hfi[params]) != hwant:", "                fail(st, hft, \"ARGCOUNT_ERROR\", cat([str(hwant), \" parameter(s) in '\", hfn, \"'\"]), cat([str(len(hfi[params])), \" parameter(s)\"]))", "                return {}", "            dict hnames = st[fnames]", "            bargs.add({k: \"func_ref\", name: hfn, lua: hnames.take(hfn), t: \"func\", line: hft[line], col: hft[col]})", "            if bn == \"reduce\":", "                expect_tok(st, \"op\", \",\", \"','\")", "                if NOT (st[err] is NONE):", "                    return {}", "                dict hstart = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return {}", "                bargs.add(hstart)", "            expect_tok(st, \"op\", \")\", \"')'\")", "        else:", "            if NOT tok_is(tk(st), \"op\", \")\"):", "                while TRUE:", "                    dict ba1 = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    bargs.add(ba1)", "                    if tok_is(tk(st), \"op\", \",\"):", "                        advance(st)", "                    else:", "                        break", "            expect_tok(st, \"op\", \")\", \"')'\")", "        if NOT (st[err] is NONE):", "            return {}", "        dict bi = builtin_info(bn)", "        bool bvari = FALSE", "        if bi.contains(\"variadic\"):", "            bvari = bi[variadic]", "        if bvari:", "            if len(bargs) < bi[min] OR len(bargs) > bi[max]:", "                fail(st, t, \"ARGCOUNT_ERROR\", cat([str(bi[min]), \"..\", str(bi[max]), \" argument(s) to '\", bn, \"'\"]), cat([str(len(bargs)), \" argument(s)\"]))", "                return {}", "        else:", "            flint np = bi[n]", "            if len(bargs) != np:", "                fail(st, t, \"ARGCOUNT_ERROR\", cat([str(np), \" argument(s) to '\", bn, \"'\"]), cat([str(len(bargs)), \" argument(s)\"]))", "                return {}", "        flint bai = 0", "        while bai < len(bargs):", "            dict ba2 = bargs[bai]", "            if bvari:", "                if len(bargs) == 1 AND (base_type(ba2[t]) == \"list\" OR ba2[t] == \"any\" OR ba2[t] == \"NONE\"):", "                    bai += 1", "                else:", "                    if NOT builtin_arg_ok(bi[a1], ba2[t]):", "                        fail(st, {line: ba2[line], col: ba2[col]}, \"TYPE_ERROR\", cat([\"argument \", str(bai + 1), \" of '\", bn, \"' to be flint\"]), ba2[t])", "                        return {}", "                    bai += 1", "            else:", "                str bspec = bi[a1]", "                if bai == 1:", "                    bspec = bi[a2]", "                elif bai == 2:", "                    bspec = bi[a3]", "                if NOT builtin_arg_ok(bspec, ba2[t]):", "                    fail(st, {line: ba2[line], col: ba2[col]}, \"TYPE_ERROR\", cat([\"argument \", str(bai + 1), \" of '\", bn, \"' to be \", builtin_arg_desc(bspec)]), ba2[t])", "                    return {}", "                bai += 1", "        if bn == \"str\" AND len(bargs) == 1:", "            dict barg0 = bargs[0]", "            if is_model_type(st, barg0[t]):", "                fail(st, barg0, \"TYPE_ERROR\", \"a field or method inside str(...), not a model instance\", barg0[t])", "                return {}", "        e = {k: \"builtin\", name: bn, args: bargs, t: bi[ret], line: t[line], col: t[col]}", "    elif ty == \"name\" AND is_template_func(t[value]):", "        pfn = t[value]", "        advance(st)", "        expect_tok(st, \"op\", \"(\", \"'('\")", "        dict tpl = expect_tok(st, \"template\", \"\", \"template\")", "        expect_tok(st, \"op\", \")\", \"')'\")", "        if NOT (st[err] is NONE):", "            return {}", "        ptok = tpl", "    elif ty == \"name\":", "        str fn = t[value]", "        if is_model_type(st, fn):", "            fail(st, t, \"TYPE_ERROR\", \"a value, not a model name\", cat([\"model '\", fn, \"'\"]))", "            return {}", "        if peek_value(st) == \"(\":", "            dict funcs = st[funcs]", "            if NOT funcs.contains(fn):", "                fail(st, t, \"NAME_ERROR\", \"declared function\", cat([\"undeclared function '\", fn, \"'\"]))", "                return {}", "            dict fi = funcs.take(fn)", "            if fi[inferring] AND fi[ret] is NONE:", "                fail(st, t, \"TYPE_ERROR\", \"explicit '->' for recursion\", cat([\"'\", fn, \"' is called while its return type is inferred\"]))", "                return {}", "            advance(st)", "            expect_tok(st, \"op\", \"(\", \"'('\")", "            list cargs = []", "            if NOT tok_is(tk(st), \"op\", \")\"):", "                while TRUE:", "                    dict ca1 = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    cargs.add(ca1)", "                    if tok_is(tk(st), \"op\", \",\"):", "                        advance(st)", "                    else:", "                        break", "            expect_tok(st, \"op\", \")\", \"')'\")", "            if NOT (st[err] is NONE):", "                return {}", "            list params = fi[params]", "            if len(cargs) != len(params):", "                fail(st, t, \"ARGCOUNT_ERROR\", cat([str(len(params)), \" argument(s) to '\", fn, \"'\"]), cat([str(len(cargs)), \" argument(s)\"]))", "                return {}", "            list ptypes = []", "            flint cai = 0", "            while cai < len(cargs):", "                dict ca2 = cargs[cai]", "                dict pp = params[cai]", "                str pt = pp[type]", "                ptypes.add(pt)", "                if ca2[t] != \"NONE\" AND ca2[t] != \"any\" AND ca2[t] != pt:", "                    fail(st, {line: ca2[line], col: ca2[col]}, \"TYPE_ERROR\", cat([\"argument \", str(cai + 1), \" of '\", fn, \"' to be \", pt]), ca2[t])", "                    return {}", "                cai += 1", "            dict fnames = st[fnames]", "            e = {k: \"call_user\", name: fn, lua: fnames.take(fn), args: cargs, ptypes: ptypes, t: fi[ret], nullable: fi[ret_nullable], line: t[line], col: t[col]}", "        else:", "            str vn = t[value]", "            dict vars = st[vars]", "            bool is_local = vars.contains(vn)", "            dict gv = st[gvars]", "            bool is_global = FALSE", "            bool is_mfield = FALSE", "            dict mctxv = st[model_ctx]", "            if NOT is_local:", "                if gv.contains(vn):", "                    is_global = TRUE", "                elif NOT (mctxv is NONE):", "                    dict ms0 = mctxv[schema]", "                    dict mf0 = ms0[model_fields]", "                    if mf0.contains(vn):", "                        is_mfield = TRUE", "                    else:", "                        fail(st, t, \"NAME_ERROR\", \"declared name\", cat([\"undeclared '\", vn, \"'\"]))", "                        return {}", "                else:", "                    fail(st, t, \"NAME_ERROR\", \"declared name\", cat([\"undeclared '\", vn, \"'\"]))", "                    return {}", "            advance(st)", "            dict names = st[names]", "            bool nl = FALSE", "            str vt = \"\"", "            if is_mfield:", "                dict ms1 = mctxv[schema]", "                dict mf1 = ms1[model_fields]", "                vt = mf1.take(vn)", "                e = {k: \"model_field\", name: vn, mname: mctxv[model_name], t: vt, line: t[line], col: t[col]}", "            else:", "                if is_local:", "                    vt = vars.take(vn)", "                    dict nd = st[nullable]", "                    if nd.contains(vn):", "                        nl = nd.take(vn)", "                    dict mu = st[maybe_unset]", "                    if mu.contains(vn):", "                        nl = TRUE", "                else:", "                    vt = gv.take(vn)", "                    dict gnl = st[gnullable]", "                    if gnl.contains(vn):", "                        nl = gnl.take(vn)", "                    dict gmu = st[gmaybe]", "                    if gmu.contains(vn):", "                        nl = TRUE", "                e = {k: \"var\", name: vn, lua: names.take(vn), t: vt, nullable: nl, line: t[line], col: t[col]}", "    elif ty == \"op\" AND t[value] == \"(\":", "        advance(st)", "        e = parse_expr(st, 0)", "        if NOT (st[err] is NONE):", "            return {}", "        expect_tok(st, \"op\", \")\", \"')'\")", "        if NOT (st[err] is NONE):", "            return {}", "    elif ty == \"op\" AND t[value] == \"[\":", "        advance(st)", "        list items = []", "        if NOT tok_is(tk(st), \"op\", \"]\"):", "            while TRUE:", "                dict it = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return {}", "                items.add(it)", "                if tok_is(tk(st), \"op\", \",\"):", "                    advance(st)", "                else:", "                    break", "        expect_tok(st, \"op\", \"]\", \"']'\")", "        if NOT (st[err] is NONE):", "            return {}", "        e = {k: \"list\", items: items, t: \"list\", line: t[line], col: t[col]}", "    elif ty == \"op\" AND t[value] == \"\\{\":", "        advance(st)", "        list pairs = []", "        if NOT tok_is(tk(st), \"op\", \"\\}\"):", "            while TRUE:", "                dict dkt = tk(st)", "                str dkey = \"\"", "                if dkt[type] == \"name\":", "                    advance(st)", "                    dkey = dkt[value]", "                elif dkt[type] == \"string\":", "                    dkey = plain_string_of(st, dkt)", "                    advance(st)", "                    if NOT (st[err] is NONE):", "                        return {}", "                else:", "                    fail(st, dkt, \"TYPE_ERROR\", \"dict dkey as bare name or string literal\", describe_tok(dkt))", "                    return {}", "                expect_tok(st, \"op\", \":\", \"':'\")", "                dict dval = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return {}", "                pairs.add({key: dkey, value: dval})", "                if tok_is(tk(st), \"op\", \",\"):", "                    advance(st)", "                else:", "                    break", "        expect_tok(st, \"op\", \"\\}\", \"'\\}'\")", "        if NOT (st[err] is NONE):", "            return {}", "        e = {k: \"dict\", pairs: pairs, t: \"dict\", line: t[line], col: t[col]}", "    elif ty == \"op\" AND t[value] == \"-\":", "        advance(st)", "        dict ua = parse_expr(st, 60)", "        if NOT (st[err] is NONE):", "            return {}", "        if NOT is_numeric(ua[t]):", "            fail(st, t, \"TYPE_ERROR\", \"operand of unary '-' to be flint\", ua[t])", "            return {}", "        e = {k: \"un\", op: \"-\", a: ua, t: \"flint\", line: t[line], col: t[col]}", "    elif ty == \"kw\" AND t[value] == \"NOT\":", "        advance(st)", "        dict na = parse_expr(st, 25)", "        if NOT (st[err] is NONE):", "            return {}", "        check_condition(st, na, {line: na[line], col: na[col]})", "        if NOT (st[err] is NONE):", "            return {}", "        e = {k: \"un\", op: \"NOT\", a: na, t: \"bool\", line: t[line], col: t[col]}", "    else:", "        fail(st, t, \"SYNTAX_ERROR\", \"expression\", describe_tok(t))", "        return {}", "", "    if NOT (ptok is NONE):", "        list parts = []", "        list raw = ptok[parts]", "        flint pi = 0", "        while pi < len(raw):", "            dict p = raw[pi]", "            if p[kind] == \"text\":", "                parts.add({kind: \"text\", value: p[value]})", "            else:", "                dict sub = template_state(st, p)", "                dict ex = parse_expr(sub, 0)", "                if NOT (sub[err] is NONE):", "                    st.add(\"err\", sub[err])", "                    return {}", "                if NOT (st[err] is NONE):", "                    return {}", "                dict rest = tk(sub)", "                if rest[type] != \"newline\" AND rest[type] != \"eof\":", "                    fail(sub, rest, \"SYNTAX_ERROR\", \"end of expression\", describe_tok(rest))", "                    st.add(\"err\", sub[err])", "                    return {}", "                if is_model_type(st, ex[t]):", "                    fail(st, {line: ex[line], col: ex[col]}, \"TYPE_ERROR\", \"a field or method inside interpolation, not a model instance\", ex[t])", "                    return {}", "                parts.add({kind: \"expr\", expr: ex})", "            pi += 1", "        if pfn == \"\":", "            e = {k: \"str\", parts: parts, t: \"str\", line: t[line], col: t[col]}", "        else:", "            str tt = \"NONE\"", "            if pfn == \"input\":", "                tt = \"str\"", "            e = {k: \"call\", fn: pfn, parts: parts, t: tt, line: t[line], col: t[col]}", "", "    # постфиксы: индексы, срезы, методы", "    bool more = TRUE", "    while more:", "        dict nt = tk(st)", "        if nt[type] == \"op\" AND nt[value] == \"[\":", "            advance(st)", "            str bt = e[t]", "            if base_type(bt) == \"dict\":", "                dict pkt = tk(st)", "                str pkey = \"\"", "                if pkt[type] == \"name\":", "                    advance(st)", "                    pkey = pkt[value]", "                elif pkt[type] == \"string\":", "                    advance(st)", "                    list prawk = pkt[parts]", "                    list pbuf = []", "                    for pp0 in prawk:", "                        dict ppd = pp0", "                        if ppd[kind] != \"text\":", "                            fail(st, pkt, \"TYPE_ERROR\", \"plain string pkey\", \"interpolated string\")", "                            return {}", "                        pbuf.add(ppd[value])", "                    pkey = pbuf.join(\"\")", "                else:", "                    fail(st, pkt, \"TYPE_ERROR\", \"dict pkey as bare name or string literal\", describe_tok(pkt))", "                    return {}", "                expect_tok(st, \"op\", \"]\", \"']'\")", "                if NOT (st[err] is NONE):", "                    return {}", "                e = {k: \"dget\", base: e, key: pkey, t: \"any\", nullable: TRUE, line: nt[line], col: nt[col]}", "            else:", "                str bbt = base_type(bt)", "                if bbt != \"str\" AND bbt != \"list\" AND bbt != \"froz\" AND bt != \"NONE\" AND bt != \"any\":", "                    fail(st, nt, \"TYPE_ERROR\", \"str, list, froz or dict receiver of an index\", bt)", "                    return {}", "                dict from = {}", "                bool has_from = FALSE", "                if NOT tok_is(tk(st), \"op\", \"..\"):", "                    from = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    has_from = TRUE", "                if tok_is(tk(st), \"op\", \"..\"):", "                    advance(st)", "                    dict to = {}", "                    bool has_to = FALSE", "                    if NOT tok_is(tk(st), \"op\", \"]\"):", "                        to = parse_expr(st, 0)", "                        if NOT (st[err] is NONE):", "                            return {}", "                        has_to = TRUE", "                    dict step = {}", "                    bool has_step = FALSE", "                    if tok_is(tk(st), \"op\", \"..\"):", "                        advance(st)", "                        step = parse_expr(st, 0)", "                        if NOT (st[err] is NONE):", "                            return {}", "                        has_step = TRUE", "                    expect_tok(st, \"op\", \"]\", \"']'\")", "                    if NOT (st[err] is NONE):", "                        return {}", "                    list bounds = []", "                    if has_from:", "                        bounds.add(from)", "                    if has_to:", "                        bounds.add(to)", "                    if has_step:", "                        bounds.add(step)", "                    for b0 in bounds:", "                        dict sb = b0", "                        if sb[t] != \"flint\" AND sb[t] != \"NONE\" AND sb[t] != \"any\":", "                            fail(st, {line: sb[line], col: sb[col]}, \"TYPE_ERROR\", \"slice bound to be flint\", sb[t])", "                            return {}", "                    str stype = \"any\"", "                    if bbt == \"list\" OR bbt == \"froz\":", "                        stype = bt", "                    elif bbt == \"str\":", "                        stype = \"str\"", "                    dict node = {k: \"slice\", base: e, t: stype, line: nt[line], col: nt[col]}", "                    if has_from:", "                        node.add(\"from\", from)", "                    else:", "                        node.add(\"from\", NONE)", "                    if has_to:", "                        node.add(\"to\", to)", "                    else:", "                        node.add(\"to\", NONE)", "                    if has_step:", "                        node.add(\"step\", step)", "                    else:", "                        node.add(\"step\", NONE)", "                    e = node", "                else:", "                    expect_tok(st, \"op\", \"]\", \"']'\")", "                    if NOT (st[err] is NONE):", "                        return {}", "                    if from[t] != \"flint\" AND from[t] != \"NONE\" AND from[t] != \"any\":", "                        fail(st, {line: from[line], col: from[col]}, \"TYPE_ERROR\", \"index to be flint\", from[t])", "                        return {}", "                    str itype = \"any\"", "                    if bt == \"str\":", "                        itype = \"str\"", "                    e = {k: \"index\", base: e, index: from, t: itype, line: nt[line], col: nt[col]}", "        elif nt[type] == \"op\" AND nt[value] == \".\":", "            advance(st)", "            dict mt = tk(st)", "            str mname = \"\"", "            if mt[type] == \"name\":", "                advance(st)", "                mname = mt[value]", "            else:", "                fail(st, mt, \"SYNTAX_ERROR\", \"field or method name\", describe_tok(mt))", "                return {}", "            str mbt = e[t]", "            if is_model_type(st, mbt):", "                dict ms = model_schema(st, mbt)", "                dict mms = ms[methods]", "                if tok_is(tk(st), \"op\", \"(\"):", "                    if NOT mms.contains(mname):", "                        fail(st, mt, \"NAME_ERROR\", cat([mbt, \" method\"]), cat([\"unknown method '\", mname, \"'\"]))", "                        return {}", "                    dict mm = mms.take(mname)", "                    advance(st)", "                    list margs = []", "                    if NOT tok_is(tk(st), \"op\", \")\"):", "                        while TRUE:", "                            dict ma = parse_expr(st, 0)", "                            if NOT (st[err] is NONE):", "                                return {}", "                            margs.add(ma)", "                            if tok_is(tk(st), \"op\", \",\"):", "                                advance(st)", "                            else:", "                                break", "                    expect_tok(st, \"op\", \")\", \"')'\")", "                    if NOT (st[err] is NONE):", "                        return {}", "                    list mparams = mm[params]", "                    if len(margs) != len(mparams):", "                        fail(st, mt, \"ARGCOUNT_ERROR\", cat([str(len(mparams)), \" argument(s) to '\", mname, \"'\"]), cat([str(len(margs)), \" argument(s)\"]))", "                        return {}", "                    list mpt = []", "                    flint mai = 0", "                    while mai < len(margs):", "                        dict mma = margs[mai]", "                        dict mmp = mparams[mai]", "                        mpt.add(mmp[type])", "                        if NOT assignable(mma[t], mmp[type]):", "                            fail(st, {line: mma[line], col: mma[col]}, \"TYPE_ERROR\", cat([\"argument \", str(mai + 1), \" of '\", mname, \"' to be \", mmp[type]]), mma[t])", "                            return {}", "                        mai += 1", "                    e = {k: \"model_method\", base: e, mname: mbt, name: mname, args: margs, ptypes: mpt, t: mm[ret], nullable: mm[ret_nullable], line: mt[line], col: mt[col]}", "                else:", "                    dict mfs = ms[model_fields]", "                    dict fts = ms[field_types]", "                    if mfs.contains(mname):", "                        e = {k: \"field\", base: e, name: mname, mname: mbt, model_field: TRUE, is_const: TRUE, t: mfs.take(mname), line: mt[line], col: mt[col]}", "                    elif fts.contains(mname):", "                        dict mcs = ms[consts]", "                        bool fconst = mcs.contains(mname)", "                        e = {k: \"field\", base: e, name: mname, mname: mbt, model_field: FALSE, is_const: fconst, t: fts.take(mname), line: mt[line], col: mt[col]}", "                    else:", "                        dict mctxf = st[model_ctx]", "                        bool self_new = FALSE", "                        if NOT (mctxf is NONE):", "                            if mctxf[in_construct] AND st[block_depth] == mctxf[level] AND mctxf[self_done] AND e[k] == \"var\" AND e[name] == \"self\" AND tok_is(tk(st), \"op\", \"=\"):", "                                self_new = TRUE", "                        if self_new:", "                            e = {k: \"field\", base: e, name: mname, mname: mbt, model_field: FALSE, is_const: FALSE, new_field: TRUE, t: \"NONE\", line: mt[line], col: mt[col]}", "                        else:", "                            fail(st, mt, \"NAME_ERROR\", cat([mbt, \" field or method\"]), cat([\"unknown field '\", mname, \"'\"]))", "                            return {}", "            else:", "                expect_tok(st, \"op\", \"(\", \"'('\")", "                list bmargs = []", "                if NOT tok_is(tk(st), \"op\", \")\"):", "                    while TRUE:", "                        dict ma2 = parse_expr(st, 0)", "                        if NOT (st[err] is NONE):", "                            return {}", "                        bmargs.add(ma2)", "                        if tok_is(tk(st), \"op\", \",\"):", "                            advance(st)", "                        else:", "                            break", "                expect_tok(st, \"op\", \")\", \"')'\")", "                if NOT (st[err] is NONE):", "                    return {}", "                if mbt == \"any\":", "                    fail(st, mt, \"TYPE_ERROR\", cat([\"typed receiver of method '\", mname, \"' (bind the value to a type first)\"]), \"any\")", "                    return {}", "                dict mi = method_info(mbt, mname)", "                if NOT mi[ok]:", "                    str mbb = base_type(mbt)", "                    if mbb == \"str\" OR mbb == \"list\" OR mbb == \"froz\" OR mbb == \"dict\" OR mbb == \"expect\":", "                        fail(st, mt, \"NAME_ERROR\", cat([mbb, \" method\"]), cat([\"unknown method '\", mname, \"'\"]))", "                    else:", "                        fail(st, mt, \"TYPE_ERROR\", cat([\"str, list, froz or dict receiver of '\", mname, \"'\"]), mbt)", "                    return {}", "                flint mn = mi[min]", "                flint mx = mi[max]", "                if len(bmargs) < mn OR len(bmargs) > mx:", "                    str want = str(mn)", "                    if mn != mx:", "                        want = cat([str(mn), \"..\", str(mx)])", "                    fail(st, mt, \"ARGCOUNT_ERROR\", cat([want, \" argument(s) to '\", mname, \"'\"]), cat([str(len(bmargs)), \" argument(s)\"]))", "                    return {}", "                flint ai2 = 0", "                while ai2 < len(bmargs):", "                    dict mma2 = bmargs[ai2]", "                    str mspec = mi[a1]", "                    if ai2 == 1:", "                        mspec = mi[a2]", "                    if mspec != \"any\" AND mma2[t] != \"NONE\" AND mma2[t] != \"any\" AND mma2[t] != mspec:", "                        fail(st, {line: mma2[line], col: mma2[col]}, \"TYPE_ERROR\", cat([\"argument \", str(ai2 + 1), \" of '\", mname, \"' to be \", mspec]), mma2[t])", "                        return {}", "                    ai2 += 1", "                e = {k: \"method\", base: e, name: mname, rt: mi[rt], args: bmargs, a1: mi[a1], a2: mi[a2], t: mi[ret], nullable: mi[nullable], line: mt[line], col: mt[col]}", "        else:", "            more = FALSE", "", "    # инфиксные операторы", "    more = TRUE", "    while more:", "        if NOT (st[err] is NONE):", "            return {}", "        dict it2 = tk(st)", "        str nty = it2[type]", "        if nty == \"op\":", "            str op = it2[value]", "            if is_compare(op):", "                if 30 <= min_bp:", "                    more = FALSE", "                else:", "                    list ops = []", "                    list operands = [e]", "                    bool go = TRUE", "                    while go:", "                        dict ot = tk(st)", "                        if ot[type] == \"op\" AND is_compare(ot[value]):", "                            advance(st)", "                            dict rhs = parse_expr(st, 31)", "                            if NOT (st[err] is NONE):", "                                return {}", "                            ops.add({op: ot[value], line: ot[line], col: ot[col]})", "                            operands.add(rhs)", "                        else:", "                            go = FALSE", "                    flint ci = 0", "                    while ci < len(ops):", "                        dict o = ops[ci]", "                        dict oa = operands[ci]", "                        dict ob = operands[ci + 1]", "                        if o[op] != \"==\" AND o[op] != \"!=\":", "                            str at = oa[t]", "                            str btv = ob[t]", "                            bool ok = (at == btv) AND (at == \"flint\" OR at == \"str\")", "                            if NOT ok AND at != \"NONE\" AND btv != \"NONE\" AND at != \"any\" AND btv != \"any\":", "                                fail(st, o, \"TYPE_ERROR\", cat([\"comparable operands of '\", o[op], \"'\"]), cat([at, \" and \", btv]))", "                                return {}", "                        ci += 1", "                    if len(ops) == 1:", "                        dict o0 = ops[0]", "                        e = {k: \"bin\", op: o0[op], a: operands[0], b: operands[1], t: \"bool\", line: o0[line], col: o0[col]}", "                    else:", "                        e = {k: \"chain\", ops: ops, operands: operands, t: \"bool\", line: e[line], col: e[col]}", "            elif op == \"OR\" OR op == \"AND\":", "                flint obp = 10", "                if op == \"AND\":", "                    obp = 20", "                if obp <= min_bp:", "                    more = FALSE", "                else:", "                    advance(st)", "                    dict orhs = parse_expr(st, obp)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    check_condition(st, e, {line: e[line], col: e[col]})", "                    check_condition(st, orhs, {line: orhs[line], col: orhs[col]})", "                    if NOT (st[err] is NONE):", "                        return {}", "                    e = {k: \"bin\", op: op, a: e, b: orhs, t: \"bool\", line: it2[line], col: it2[col]}", "            elif op == \"+\" OR op == \"-\" OR op == \"*\" OR op == \"/\" OR op == \"//\" OR op == \"%\":", "                flint abp = 40", "                if op == \"*\" OR op == \"/\" OR op == \"//\" OR op == \"%\":", "                    abp = 50", "                if abp <= min_bp:", "                    more = FALSE", "                else:", "                    advance(st)", "                    dict arhs = parse_expr(st, abp)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    if op == \"+\" AND (e[t] == \"str\" OR arhs[t] == \"str\"):", "                        fail(st, it2, \"CONCATENATE_NOT_SUPPORT\", \"numeric operands of '+'\", \"str\")", "                        return {}", "                    if NOT (is_numeric(e[t]) AND is_numeric(arhs[t])):", "                        fail(st, it2, \"TYPE_ERROR\", cat([\"operands of '\", op, \"' to be flint\"]), cat([e[t], \" and \", arhs[t]]))", "                        return {}", "                    e = {k: \"bin\", op: op, a: e, b: arhs, t: \"flint\", line: it2[line], col: it2[col]}", "            elif op == \"**\":", "                if 70 <= min_bp:", "                    more = FALSE", "                else:", "                    advance(st)", "                    dict prhs = parse_expr(st, 69)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    if NOT (is_numeric(e[t]) AND is_numeric(prhs[t])):", "                        fail(st, it2, \"TYPE_ERROR\", \"operands of '**' to be flint\", cat([e[t], \" and \", prhs[t]]))", "                        return {}", "                    e = {k: \"bin\", op: \"**\", a: e, b: prhs, t: \"flint\", line: it2[line], col: it2[col]}", "            else:", "                more = FALSE", "        elif nty == \"kw\" AND (it2[value] == \"OR\" OR it2[value] == \"AND\"):", "            str lop = it2[value]", "            flint lbp = 10", "            if lop == \"AND\":", "                lbp = 20", "            if lbp <= min_bp:", "                more = FALSE", "            else:", "                advance(st)", "                dict lrhs = parse_expr(st, lbp)", "                if NOT (st[err] is NONE):", "                    return {}", "                check_condition(st, e, {line: e[line], col: e[col]})", "                check_condition(st, lrhs, {line: lrhs[line], col: lrhs[col]})", "                if NOT (st[err] is NONE):", "                    return {}", "                e = {k: \"bin\", op: lop, a: e, b: lrhs, t: \"bool\", line: it2[line], col: it2[col]}", "        elif nty == \"kw\" AND it2[value] == \"is\":", "            if 30 <= min_bp:", "                more = FALSE", "            else:", "                advance(st)", "                str tn = parse_type_name(st)", "                if NOT (st[err] is NONE):", "                    return {}", "                e = {k: \"is\", a: e, typename: tn, t: \"bool\", line: it2[line], col: it2[col]}", "        else:", "            more = FALSE", "", "    return e", "", "# panic(\"CATEGORY\"[, \"message\"]). Категория и сообщение — plain-строки.", "func parse_panic(dict st) -> dict:", "    dict ptok = advance(st)", "    expect_tok(st, \"op\", \"(\", \"'('\")", "    if NOT (st[err] is NONE):", "        return {}", "    dict ct = parse_expr(st, 0)", "    if NOT (st[err] is NONE):", "        return {}", "    if ct[k] != \"str\":", "        fail(st, {line: ct[line], col: ct[col]}, \"TYPE_ERROR\", \"string panic category\", ct[t])", "        return {}", "    str catv = plain_string_of(st, ct)", "    if NOT (st[err] is NONE):", "        return {}", "    if NOT is_error_category(catv):", "        fail(st, {line: ct[line], col: ct[col]}, \"VALUE_ERROR\", \"known error category\", catv)", "        return {}", "    str msg = catv", "    if tok_is(tk(st), \"op\", \",\"):", "        advance(st)", "        dict mt = parse_expr(st, 0)", "        if NOT (st[err] is NONE):", "            return {}", "        if mt[k] != \"str\":", "            fail(st, {line: mt[line], col: mt[col]}, \"TYPE_ERROR\", \"string panic message\", mt[t])", "            return {}", "        msg = plain_string_of(st, mt)", "        if NOT (st[err] is NONE):", "            return {}", "    expect_tok(st, \"op\", \")\", \"')'\")", "    if NOT (st[err] is NONE):", "        return {}", "    return {k: \"panic\", cat: catv, msg: msg, line: ptok[line], col: ptok[col]}", "", "# ---------- парсер: операторы ----------", "", "func stmt_is_decl(dict st) -> bool:", "    dict t = tk(st)", "    dict nx = token_at(st, st[pos] + 1)", "    if t[type] == \"name\" AND is_model_type(st, t[value]):", "        return nx[type] == \"name\"", "    if t[type] != \"kw\":", "        return FALSE", "    str v = t[value]", "    if NOT is_type_keyword(v):", "        return FALSE", "    if nx[type] == \"op\" AND nx[value] == \"(\" AND (v == \"str\" OR v == \"flint\"):", "        return FALSE", "    return TRUE", "", "# Блок типов: `str:`, `flint:` и т.д. Отличается от обычного объявления", "# двоеточием сразу после типа.", "func stmt_is_decl_block(dict st) -> bool:", "    dict t = tk(st)", "    if t[type] != \"kw\":", "        return FALSE", "    if NOT is_type_keyword(t[value]):", "        return FALSE", "    dict nx = token_at(st, st[pos] + 1)", "    return nx[type] == \"op\" AND nx[value] == \":\"", "", "# Куда пишет присваивание: в локальную (или верхнеуровневую) или в глобальную.", "# Зону изменений открывают только функция и цикл. Условие — не зона: если", "# присваивание лежит внутри if/elif/else, оно запрещено даже внутри функции.", "func top_write_forbidden(dict st, str n) -> bool:", "    dict allg = st[gvars]", "    if NOT allg.contains(n):", "        return FALSE", "    if st[cond_depth] > 0:", "        return TRUE", "    return NOT st[in_func] AND st[loop_depth] == 0", "", "func resolve_write(dict st, dict tok, str n) -> dict:", "    if n == \"error\":", "        fail(st, tok, \"CONST_ERROR\", \"variable\", cat([\"handler variable '\", n, \"' is read-only\"]))", "        return {}", "    dict vars = st[vars]", "    dict gv = st[gvars]", "    if vars.contains(n):", "        if is_const_name(n):", "            fail(st, tok, \"CONST_ERROR\", \"variable\", cat([\"constant '\", n, \"'\"]))", "            return {}", "        if top_write_forbidden(st, n):", "            fail(st, tok, \"TOPLEVEL_ERROR\", \"assignment inside a nested block\", cat([\"assignment to top-level variable '\", n, \"'\"]))", "            return {}", "        dict nm = st[names]", "        return {kind: \"local\", type: vars.take(n), lua: nm.take(n)}", "    if gv.contains(n):", "        if is_const_name(n):", "            fail(st, tok, \"CONST_ERROR\", \"variable\", cat([\"constant '\", n, \"'\"]))", "            return {}", "        if top_write_forbidden(st, n):", "            fail(st, tok, \"TOPLEVEL_ERROR\", \"assignment inside a nested block\", cat([\"assignment to top-level variable '\", n, \"'\"]))", "            return {}", "        dict nm2 = st[names]", "        return {kind: \"global\", type: gv.take(n), lua: nm2.take(n)}", "    fail(st, tok, \"NAME_ERROR\", \"declared variable\", cat([\"name '\", n, \"' is not declared\"]))", "    return {}", "", "# Объявление `имя = выражение` с заданным типом. Общее для обычного", "# объявления и для строки внутри блока типов.", "func parse_typed_decl(dict st, str dty, dict dname_tok) -> dict:", "    str dname = dname_tok[value]", "    if is_reserved(dname):", "        fail(st, dname_tok, \"NAME_ERROR\", \"free name\", cat([\"reserved '\", dname, \"'\"]))", "        return {}", "    dict dvars = st[vars]", "    dict dfuncs = st[funcs]", "    if dvars.contains(dname) OR dfuncs.contains(dname):", "        fail(st, dname_tok, \"REDECLARE_ERROR\", \"unique name\", cat([\"name '\", dname, \"' is already declared\"]))", "        return {}", "    if st[in_func]:", "        dict dg = st[gvars]", "        if dg.contains(dname):", "            fail(st, dname_tok, \"REDECLARE_ERROR\", \"local name\", cat([\"global '\", dname, \"' is already declared\"]))", "            return {}", "    dict dctx = st[model_ctx]", "    if NOT (dctx is NONE):", "        dict dms = dctx[schema]", "        dict dft = dms[field_types]", "        dict dmeth = dms[methods]", "        if dft.contains(dname) OR dmeth.contains(dname):", "            fail(st, dname_tok, \"REDECLARE_ERROR\", \"local name\", cat([\"model member '\", dname, \"'\"]))", "            return {}", "    expect_tok(st, \"op\", \"=\", \"'='\")", "    if NOT (st[err] is NONE):", "        return {}", "    dict dexpr = {}", "    if is_model_type(st, dty) AND tok_is(tk(st), \"kw\", \"init\"):", "        dict inittok = advance(st)", "        expect_tok(st, \"op\", \"(\", \"'('\")", "        dict ms = model_schema(st, dty)", "        dict cons = ms[ctor]", "        if cons is NONE:", "            fail(st, inittok, \"NAME_ERROR\", cat([\"declared construct of '\", dty, \"'\"]), \"model without construct\")", "            return {}", "        list iparams = cons[params]", "        dict iparm = {}", "        flint ii = 0", "        while ii < len(iparams):", "            dict ipp = iparams[ii]", "            iparm.add(ipp[name], TRUE)", "            ii += 1", "        list iargs = []", "        dict iseen = {}", "        if NOT tok_is(tk(st), \"op\", \")\"):", "            while TRUE:", "                dict iat = expect_tok(st, \"name\", \"\", \"init argument name\")", "                if NOT (st[err] is NONE):", "                    return {}", "                str ian = iat[value]", "                if iseen.contains(ian):", "                    fail(st, iat, \"REDECLARE_ERROR\", \"unique init argument\", cat([\"duplicate '\", ian, \"'\"]))", "                    return {}", "                iseen.add(ian, TRUE)", "                expect_tok(st, \"op\", \":\", \"':'\")", "                dict iav = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return {}", "                bool iok = FALSE", "                str iwant = \"any\"", "                if iparm.contains(ian):", "                    flint ij = 0", "                    while ij < len(iparams):", "                        dict ipj = iparams[ij]", "                        if ipj[name] == ian:", "                            iwant = ipj[type]", "                            iok = TRUE", "                        ij += 1", "                else:", "                    dict iinit = ms[init_fields]", "                    dict ift = ms[field_types]", "                    dict imf = ms[model_fields]", "                    dict icons = ms[consts]", "                    if iinit.contains(ian):", "                        iwant = ift.take(ian)", "                        iok = TRUE", "                    elif imf.contains(ian) OR icons.contains(ian):", "                        fail(st, iat, \"CONST_ERROR\", \"init argument for a mutable field\", cat([\"read-only '\", ian, \"'\"]))", "                        return {}", "                    elif ift.contains(ian):", "                        fail(st, iat, \"CONST_ERROR\", \"init argument for a computed field\", cat([\"field '\", ian, \"' is set from construct parameters\"]))", "                        return {}", "                    else:", "                        fail(st, iat, \"NAME_ERROR\", cat([\"field or construct parameter of '\", dty, \"'\"]), cat([\"unknown '\", ian, \"'\"]))", "                        return {}", "                if NOT assignable(iav[t], iwant):", "                    fail(st, {line: iav[line], col: iav[col]}, \"TYPE_ERROR\", cat([\"init argument '\", ian, \"': type \", iwant]), iav[t])", "                    return {}", "                iargs.add({name: ian, expr: iav, type: iwant})", "                if tok_is(tk(st), \"op\", \",\"):", "                    advance(st)", "                else:", "                    break", "        expect_tok(st, \"op\", \")\", \"')'\")", "        if NOT (st[err] is NONE):", "            return {}", "        flint mi2 = 0", "        while mi2 < len(iparams):", "            dict ipm = iparams[mi2]", "            str need = ipm[name]", "            if NOT iseen.contains(need):", "                fail(st, inittok, \"ARGCOUNT_ERROR\", cat([\"argument '\", need, \"' in init\"]), \"missing\")", "                return {}", "            mi2 += 1", "        dexpr = {k: \"model_init\", mname: dty, args: iargs, t: dty, line: inittok[line], col: inittok[col]}", "    else:", "        dexpr = parse_expr(st, 0)", "        if NOT (st[err] is NONE):", "            return {}", "        if NOT assignable(dexpr[t], dty):", "            bool litok = FALSE", "            if is_typed_spec(dty) AND dexpr[t] != \"NONE\":", "                litok = literal_ok(st, dexpr, dty)", "            if NOT litok:", "                fail(st, {line: dexpr[line], col: dexpr[col]}, \"TYPE_ERROR\", cat([\"declaration of '\", dname, \"': type \", dty]), dexpr[t])", "                return {}", "    str dlua = mangle_var(st, dname)", "    dvars.add(dname, dty)", "    # Любое объявление вне функции — глобальная («верх файла»).", "    # Переприсвоить её можно только в функции или цикле, не в условии.", "    if NOT st[in_func]:", "        dict dtg = st[gvars]", "        dtg.add(dname, dty)", "    dict dnl = st[nullable]", "    if dexpr[t] == \"NONE\" OR e_nullable(dexpr):", "        dnl.add(dname, TRUE)", "    else:", "        dnl.remove(dname)", "    if st[block_depth] > 0:", "        dict dmu = st[maybe_unset]", "        dmu.add(dname, TRUE)", "    return {k: \"decl\", type: dty, name: dname, lua: dlua, expr: dexpr, line: dname_tok[line], col: dname_tok[col]}", "", "func snapshot_parser(dict st) -> dict:", "    return {vars: st[vars], nullable: st[nullable], maybe_unset: st[maybe_unset], for_names: st[for_names], gvars: st[gvars], gnullable: st[gnullable], gmaybe: st[gmaybe], loop_depth: st[loop_depth], cond_depth: st[cond_depth], try_depth: st[try_depth], try_loop_base: st[try_loop_base], in_func: st[in_func], func_ret: st[func_ret], func_returns: st[func_returns], model_ctx: st[model_ctx]}", "", "func restore_parser(dict st, dict sv):", "    st.add(\"vars\", sv[vars])", "    st.add(\"nullable\", sv[nullable])", "    st.add(\"maybe_unset\", sv[maybe_unset])", "    st.add(\"for_names\", sv[for_names])", "    st.add(\"gvars\", sv[gvars])", "    st.add(\"gnullable\", sv[gnullable])", "    st.add(\"gmaybe\", sv[gmaybe])", "    st.add(\"loop_depth\", sv[loop_depth])", "    st.add(\"cond_depth\", sv[cond_depth])", "    st.add(\"try_depth\", sv[try_depth])", "    st.add(\"try_loop_base\", sv[try_loop_base])", "    st.add(\"in_func\", sv[in_func])", "    st.add(\"func_ret\", sv[func_ret])", "    st.add(\"func_returns\", sv[func_returns])", "    st.add(\"model_ctx\", sv[model_ctx])", "", "# Заголовок модели: поле до construct. Тело не разбирает.", "func parse_model_field_decl(dict st, dict m) -> dict:", "    str mfty = advance(st)[value]", "    dict mfnt = expect_tok(st, \"name\", \"\", \"field name\")", "    if NOT (st[err] is NONE):", "        return {}", "    str mfname = mfnt[value]", "    check_field_name(st, mfnt, mfname)", "    if NOT (st[err] is NONE):", "        return {}", "    dict mf = m[model_fields]", "    dict ft = m[field_types]", "    dict meth = m[methods]", "    if mf.contains(mfname) OR ft.contains(mfname) OR meth.contains(mfname):", "        fail(st, mfnt, \"REDECLARE_ERROR\", \"unique field name\", cat([\"name '\", mfname, \"' is already declared\"]))", "        return {}", "    expect_tok(st, \"op\", \"=\", \"'='\")", "    dict sv = st[model_ctx]", "    st.add(\"model_ctx\", NONE)", "    dict mfexpr = parse_expr(st, 0)", "    st.add(\"model_ctx\", sv)", "    if NOT (st[err] is NONE):", "        return {}", "    if NOT assignable(mfexpr[t], mfty):", "        fail(st, {line: mfexpr[line], col: mfexpr[col]}, \"TYPE_ERROR\", cat([\"field '\", mfname, \"': type \", mfty]), mfexpr[t])", "        return {}", "    mf.add(mfname, mfty)", "    ft.add(mfname, mfty)", "    list mo = m[order]", "    mo.add(mfname)", "    list fo = m[field_order]", "    fo.add(mfname)", "    return {name: mfname, type: mfty, expr: mfexpr, line: mfnt[line], col: mfnt[col]}", "", "# Параметры construct (construct=TRUE) или метода. Скобки уже открыты.", "func parse_model_params(dict st, dict m, bool is_cons) -> list:", "    list out = []", "    if NOT tok_is(tk(st), \"op\", \")\"):", "        while TRUE:", "            dict pty_tok = tk(st)", "            str pty = parse_type_name(st)", "            if NOT (st[err] is NONE):", "                return out", "            if pty == \"NONE\":", "                fail(st, pty_tok, \"TYPE_ERROR\", \"parameter type\", \"NONE\")", "                return out", "            dict pnt = expect_tok(st, \"name\", \"\", \"parameter name\")", "            if NOT (st[err] is NONE):", "                return out", "            str pnm = pnt[value]", "            if is_reserved(pnm) OR is_const_name(pnm):", "                fail(st, pnt, \"NAME_ERROR\", \"free parameter name\", cat([\"reserved '\", pnm, \"'\"]))", "                return out", "            dict mf = m[model_fields]", "            dict ft = m[field_types]", "            dict meth = m[methods]", "            if mf.contains(pnm) OR meth.contains(pnm) OR (NOT is_cons AND ft.contains(pnm)):", "                fail(st, pnt, \"REDECLARE_ERROR\", \"parameter name\", cat([\"model member '\", pnm, \"'\"]))", "                return out", "            flint pi = 0", "            while pi < len(out):", "                dict po = out[pi]", "                if po[name] == pnm:", "                    fail(st, pnt, \"REDECLARE_ERROR\", \"unique parameter name\", cat([\"duplicate '\", pnm, \"'\"]))", "                    return out", "                pi += 1", "            out.add({name: pnm, type: pty, line: pnt[line], col: pnt[col]})", "            if tok_is(tk(st), \"op\", \",\"):", "                advance(st)", "            else:", "                break", "    expect_tok(st, \"op\", \")\", \"')'\")", "    return out", "", "func parse_construct_header(dict st, dict m) -> dict:", "    advance(st)", "    expect_tok(st, \"op\", \"(\", \"'('\")", "    list params = parse_model_params(st, m, TRUE)", "    if NOT (st[err] is NONE):", "        return {}", "    expect_tok(st, \"op\", \":\", \"':'\")", "    if NOT (st[err] is NONE):", "        return {}", "    m.add(\"ctor\", {params: params, body: []})", "    list mparams = m[params]", "    dict mptypes = m[param_types]", "    for p0 in params:", "        dict p = p0", "        mparams.add(p[name])", "        mptypes.add(p[name], p[type])", "    dict mctx = {model_name: m[name], schema: m, in_construct: TRUE, level: st[block_depth] + 1, self_seen: FALSE, self_done: FALSE, param_set: {}}", "    dict ps = mctx[param_set]", "    for p1 in params:", "        dict p1d = p1", "        ps.add(p1d[name], TRUE)", "    return {params: params, mctx: mctx}", "", "func parse_method_header(dict st, dict m) -> dict:", "    advance(st)", "    dict mtok = expect_tok(st, \"name\", \"\", \"method name\")", "    if NOT (st[err] is NONE):", "        return {}", "    str mn = mtok[value]", "    if is_reserved(mn) OR is_const_name(mn):", "        fail(st, mtok, \"NAME_ERROR\", \"free method name\", cat([\"reserved '\", mn, \"'\"]))", "        return {}", "    dict mf = m[model_fields]", "    dict ft = m[field_types]", "    dict meth = m[methods]", "    if ft.contains(mn) OR mf.contains(mn) OR meth.contains(mn):", "        fail(st, mtok, \"REDECLARE_ERROR\", \"unique method name\", cat([\"name '\", mn, \"' is already declared\"]))", "        return {}", "    expect_tok(st, \"op\", \"(\", \"'('\")", "    list params = parse_model_params(st, m, FALSE)", "    if NOT (st[err] is NONE):", "        return {}", "    str mret = \"NONE\"", "    bool mhas = FALSE", "    if tok_is(tk(st), \"op\", \"->\"):", "        advance(st)", "        dict mrt = tk(st)", "        mret = parse_type_name(st)", "        if NOT (st[err] is NONE):", "            return {}", "        if mret == \"NONE\":", "            fail(st, mrt, \"SYNTAX_ERROR\", \"return type (omit '->' for NONE)\", \"NONE\")", "            return {}", "        mhas = TRUE", "    expect_tok(st, \"op\", \":\", \"':'\")", "    if NOT (st[err] is NONE):", "        return {}", "    dict info = {params: params, ret: NONE, ret_nullable: FALSE, inferring: TRUE}", "    if mhas:", "        info.add(\"ret\", mret)", "    meth.add(mn, info)", "    list mo = m[method_order]", "    mo.add(mn)", "    return {name: mn, info: info, params: params, ret: mret, has_ret: mhas, line: mtok[line], col: mtok[col]}", "", "func finish_method(dict st, dict info, list body, str declared, bool has_ret, list rets):", "    bool fall = TRUE", "    if len(body) > 0:", "        dict last = body[len(body) - 1]", "        if last[k] == \"return\":", "            fall = FALSE", "    bool nullable = fall", "    str seen = \"\"", "    flint ri = 0", "    while ri < len(rets):", "        dict rr = rets[ri]", "        if rr[empty] OR rr[type] == \"NONE\" OR e_nullable(rr):", "            nullable = TRUE", "        elif has_ret:", "            if rr[type] != declared AND rr[type] != \"any\":", "                fail(st, rr, \"TYPE_ERROR\", cat([\"return type \", declared]), rr[type])", "                return:", "        else:", "            if seen != \"\" AND seen != rr[type]:", "                fail(st, rr, \"TYPE_ERROR\", \"all returns of a method to have one type\", cat([seen, \" and \", rr[type]]))", "                return:", "            seen = rr[type]", "        ri += 1", "    str final = declared", "    if NOT has_ret:", "        final = seen", "        if final == \"\":", "            final = \"NONE\"", "    info.add(\"ret\", final)", "    info.add(\"ret_nullable\", nullable)", "    info.add(\"inferring\", FALSE)", "    info.add(\"body\", body)", "", "# Разбирает блок. top=TRUE — весь файл до eof; top=FALSE — после ':'.", "# Рекурсивна: тела if/while/for/func разбираются ею же.", "func enter_try_zone(dict st, flint old_base):", "    st.add(\"try_depth\", st[try_depth] + 1)", "    flint base = old_base", "    if st[loop_depth] > base:", "        base = st[loop_depth]", "    st.add(\"try_loop_base\", base)", "", "func leave_try_zone(dict st, flint old_base):", "    st.add(\"try_depth\", st[try_depth] - 1)", "    st.add(\"try_loop_base\", old_base)", "", "func try_crosses_loop(dict st) -> bool:", "    return st[try_depth] > 0 AND st[loop_depth] <= st[try_loop_base]", "", "func add_handler_error(dict st) -> dict:", "    dict old_names = st[names]", "    dict old_vars = st[vars]", "    dict old_null = st[nullable]", "    dict old_maybe = st[maybe_unset]", "    bool had_name = old_names.contains(\"error\")", "    bool had_var = old_vars.contains(\"error\")", "    bool had_null = old_null.contains(\"error\")", "    bool had_maybe = old_maybe.contains(\"error\")", "    str prev_name = \"\"", "    str prev_var = \"\"", "    bool prev_null = FALSE", "    bool prev_maybe = FALSE", "    if had_name:", "        prev_name = old_names.take(\"error\")", "    if had_var:", "        prev_var = old_vars.take(\"error\")", "    if had_null:", "        prev_null = old_null.take(\"error\")", "    if had_maybe:", "        prev_maybe = old_maybe.take(\"error\")", "    old_names.add(\"error\", \"error\")", "    old_vars.add(\"error\", \"Error\")", "    return {name: had_name, var: had_var, null: had_null, maybe: had_maybe, prev_name: prev_name, prev_var: prev_var, prev_null: prev_null, prev_maybe: prev_maybe}", "", "func remove_handler_error(dict st, dict sv):", "    dict cur_names = st[names]", "    dict cur_vars = st[vars]", "    dict cur_null = st[nullable]", "    dict cur_maybe = st[maybe_unset]", "    cur_names.remove(\"error\")", "    cur_vars.remove(\"error\")", "    cur_null.remove(\"error\")", "    cur_maybe.remove(\"error\")", "    if sv[name]:", "        cur_names.add(\"error\", sv[prev_name])", "    if sv[var]:", "        cur_vars.add(\"error\", sv[prev_var])", "    if sv[null]:", "        cur_null.add(\"error\", sv[prev_null])", "    if sv[maybe]:", "        cur_maybe.add(\"error\", sv[prev_maybe])", "", "func parse_block(dict st, bool top) -> list:", "    list stmts = []", "    if NOT top:", "        expect_tok(st, \"newline\", \"\", \"end of line after ':'\")", "        expect_tok(st, \"indent\", \"\", \"indented block\")", "        st.add(\"block_depth\", st[block_depth] + 1)", "    bool going = TRUE", "    while going:", "        dict t = tk(st)", "        if NOT (st[err] is NONE):", "            return stmts", "        bool skip = FALSE", "        if top:", "            if t[type] == \"eof\":", "                going = FALSE", "                skip = TRUE", "            elif t[type] == \"newline\" OR t[type] == \"dedent\":", "                advance(st)", "                skip = TRUE", "            elif t[type] == \"indent\":", "                fail(st, t, \"SYNTAX_ERROR\", \"statement\", \"unexpected indent\")", "                return stmts", "        else:", "            if t[type] == \"dedent\" OR t[type] == \"eof\":", "                going = FALSE", "                skip = TRUE", "            elif t[type] == \"newline\":", "                advance(st)", "                skip = TRUE", "        if going AND NOT skip:", "            dict node = {}", "            bool block_stmt = FALSE", "            bool decl_block = FALSE", "            if stmt_is_decl_block(st):", "                dict dbtok = advance(st)", "                str dbty = dbtok[value]", "                advance(st)", "                expect_tok(st, \"newline\", \"\", \"end of line after ':'\")", "                expect_tok(st, \"indent\", \"\", \"indented block\")", "                if NOT (st[err] is NONE):", "                    return stmts", "                flint dcount = 0", "                bool dbgoing = TRUE", "                while dbgoing:", "                    dict dbt = tk(st)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    if dbt[type] == \"dedent\" OR dbt[type] == \"eof\":", "                        dbgoing = FALSE", "                    elif dbt[type] == \"newline\":", "                        advance(st)", "                    else:", "                        dict dbnt = expect_tok(st, \"name\", \"\", \"variable name\")", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        dict dbdecl = parse_typed_decl(st, dbty, dbnt)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        stmts.add(dbdecl)", "                        dcount += 1", "                        dict dbnxt = tk(st)", "                        if dbnxt[type] == \"newline\":", "                            advance(st)", "                        elif dbnxt[type] != \"dedent\":", "                            fail(st, dbnxt, \"SYNTAX_ERROR\", \"end of line\", describe_tok(dbnxt))", "                            return stmts", "                if tk(st)[type] == \"dedent\":", "                    advance(st)", "                if dcount == 0:", "                    fail(st, dbtok, \"SYNTAX_ERROR\", \"declaration inside type block\", \"empty block\")", "                    return stmts", "                decl_block = TRUE", "            elif stmt_is_decl(st):", "                str dty = parse_type_name(st)", "                if NOT (st[err] is NONE):", "                    return stmts", "                dict dname_tok = expect_tok(st, \"name\", \"\", \"variable name\")", "                if NOT (st[err] is NONE):", "                    return stmts", "                node = parse_typed_decl(st, dty, dname_tok)", "                if NOT (st[err] is NONE):", "                    return stmts", "            elif t[type] == \"kw\" AND t[value] == \"panic\":", "                node = parse_panic(st)", "                if NOT (st[err] is NONE):", "                    return stmts", "            elif t[type] == \"kw\" AND t[value] == \"if\":", "                dict iftok = advance(st)", "                list branches = []", "                dict cond = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return stmts", "                check_condition(st, cond, {line: cond[line], col: cond[col]})", "                if NOT (st[err] is NONE):", "                    return stmts", "                expect_tok(st, \"op\", \":\", \"':'\")", "                st.add(\"cond_depth\", st[cond_depth] + 1)", "                list ibody = parse_block(st, FALSE)", "                st.add(\"cond_depth\", st[cond_depth] - 1)", "                branches.add({cond: cond, body: ibody})", "                while tok_is(tk(st), \"kw\", \"elif\"):", "                    advance(st)", "                    dict c2 = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    check_condition(st, c2, {line: c2[line], col: c2[col]})", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    expect_tok(st, \"op\", \":\", \"':'\")", "                    st.add(\"cond_depth\", st[cond_depth] + 1)", "                    list b2 = parse_block(st, FALSE)", "                    st.add(\"cond_depth\", st[cond_depth] - 1)", "                    branches.add({cond: c2, body: b2})", "                node = {k: \"if\", branches: branches, block_stmt: TRUE, line: iftok[line], col: iftok[col]}", "                if tok_is(tk(st), \"kw\", \"else\"):", "                    advance(st)", "                    expect_tok(st, \"op\", \":\", \"':'\")", "                    st.add(\"cond_depth\", st[cond_depth] + 1)", "                    list eb = parse_block(st, FALSE)", "                    st.add(\"cond_depth\", st[cond_depth] - 1)", "                    node.add(\"else_body\", eb)", "                block_stmt = TRUE", "            elif t[type] == \"kw\" AND t[value] == \"while\":", "                dict wtok = advance(st)", "                dict wcond = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return stmts", "                check_condition(st, wcond, {line: wcond[line], col: wcond[col]})", "                if NOT (st[err] is NONE):", "                    return stmts", "                expect_tok(st, \"op\", \":\", \"':'\")", "                st.add(\"loop_depth\", st[loop_depth] + 1)", "                list wbody = parse_block(st, FALSE)", "                st.add(\"loop_depth\", st[loop_depth] - 1)", "                node = {k: \"while\", cond: wcond, body: wbody, block_stmt: TRUE, line: wtok[line], col: wtok[col]}", "                block_stmt = TRUE", "            elif t[type] == \"kw\" AND t[value] == \"try\":", "                dict trytok = advance(st)", "                expect_tok(st, \"op\", \":\", \"':'\")", "                flint zbase = st[try_loop_base]", "                enter_try_zone(st, zbase)", "                list try_body = parse_block(st, FALSE)", "                leave_try_zone(st, zbase)", "                if NOT (st[err] is NONE):", "                    return stmts", "                list ztriggers = []", "                dict zany = NONE", "                dict zcats = {}", "                while tok_is(tk(st), \"kw\", \"trigger\"):", "                    dict trtok = advance(st)", "                    dict zcattok = expect_tok(st, \"name\", \"\", \"error category\")", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    if NOT is_error_category(zcattok[value]):", "                        fail(st, zcattok, \"NAME_ERROR\", \"known error category\", zcattok[value])", "                        return stmts", "                    if NOT (zany is NONE):", "                        fail(st, zcattok, \"SYNTAX_ERROR\", \"trigger after ANY_ERROR\", cat([\"'\", zcattok[value], \"'\"]))", "                        return stmts", "                    if zcattok[value] != \"ANY_ERROR\":", "                        if zcats.contains(zcattok[value]):", "                            fail(st, zcattok, \"REDECLARE_ERROR\", \"unique trigger category\", cat([\"'\", zcattok[value], \"'\"]))", "                            return stmts", "                        zcats.add(zcattok[value], TRUE)", "                    expect_tok(st, \"op\", \":\", \"':'\")", "                    enter_try_zone(st, zbase)", "                    dict hsv = add_handler_error(st)", "                    list hbody = parse_block(st, FALSE)", "                    remove_handler_error(st, hsv)", "                    leave_try_zone(st, zbase)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    dict hnode = {cat: zcattok[value], body: hbody, line: trtok[line], col: trtok[col]}", "                    if zcattok[value] == \"ANY_ERROR\":", "                        zany = hnode", "                    else:", "                        ztriggers.add(hnode)", "                if len(ztriggers) == 0 AND zany is NONE:", "                    fail(st, trytok, \"SYNTAX_ERROR\", \"trigger after try\", \"finally\")", "                    return stmts", "                if NOT tok_is(tk(st), \"kw\", \"finally\"):", "                    fail(st, tk(st), \"SYNTAX_ERROR\", \"'finally:'\", describe_tok(tk(st)))", "                    return stmts", "                advance(st)", "                expect_tok(st, \"op\", \":\", \"':'\")", "                enter_try_zone(st, zbase)", "                list zfinally = parse_block(st, FALSE)", "                leave_try_zone(st, zbase)", "                if NOT (st[err] is NONE):", "                    return stmts", "                node = {k: \"try\", body: try_body, triggers: ztriggers, any: zany, \"finally\": zfinally, block_stmt: TRUE, line: trytok[line], col: trytok[col]}", "                block_stmt = TRUE", "            elif t[type] == \"kw\" AND t[value] == \"for\":", "                dict ftok = advance(st)", "                list nts = []", "                dict nt1 = expect_tok(st, \"name\", \"\", \"loop variable\")", "                nts.add(nt1)", "                if tok_is(tk(st), \"op\", \",\"):", "                    advance(st)", "                    dict nt2 = expect_tok(st, \"name\", \"\", \"loop variable\")", "                    nts.add(nt2)", "                if tok_is(tk(st), \"kw\", \"in\"):", "                    advance(st)", "                    dict coll = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    list ftypes = []", "                    str cty = base_type(coll[t])", "                    if cty == \"list\":", "                        if len(nts) != 1:", "                            fail(st, nts[1], \"TYPE_ERROR\", \"one loop variable for a list\", \"two variables\")", "                            return stmts", "                        ftypes.add(\"any\")", "                    elif cty == \"froz\":", "                        if len(nts) != 1:", "                            fail(st, nts[1], \"TYPE_ERROR\", \"one loop variable for a froz\", \"two variables\")", "                            return stmts", "                        ftypes.add(\"any\")", "                    elif cty == \"dict\":", "                        if len(nts) != 2:", "                            fail(st, nts[0], \"TYPE_ERROR\", \"two loop variables for a dict (key, value)\", \"one variable\")", "                            return stmts", "                        ftypes.add(\"str\")", "                        ftypes.add(\"any\")", "                    elif cty == \"any\":", "                        if len(nts) == 1:", "                            ftypes.add(\"any\")", "                        else:", "                            ftypes.add(\"str\")", "                            ftypes.add(\"any\")", "                    else:", "                        fail(st, ftok, \"TYPE_ERROR\", \"list or dict after 'in'\", cty)", "                        return stmts", "                    list fnames_k = []", "                    list fnames_l = []", "                    flint ni = 0", "                    while ni < len(nts):", "                        dict ntx = nts[ni]", "                        str nm = ntx[value]", "                        if is_const_name(nm):", "                            fail(st, ntx, \"CONST_ERROR\", \"variable\", cat([\"constant '\", nm, \"'\"]))", "                            return stmts", "                        if is_reserved(nm):", "                            fail(st, ntx, \"NAME_ERROR\", \"free name\", cat([\"reserved '\", nm, \"'\"]))", "                            return stmts", "                        dict fvars = st[vars]", "                        dict ffor = st[for_names]", "                        dict fgv = st[gvars]", "                        if fvars.contains(nm) OR ffor.contains(nm) OR fgv.contains(nm):", "                            fail(st, ntx, \"REDECLARE_ERROR\", \"unique loop variable\", cat([\"name '\", nm, \"' is already declared\"]))", "                            return stmts", "                        fvars.add(nm, ftypes[ni])", "                        ffor.add(nm, TRUE)", "                        fnames_k.add(nm)", "                        fnames_l.add(mangle_var(st, nm))", "                        ni += 1", "                    expect_tok(st, \"op\", \":\", \"':'\")", "                    st.add(\"loop_depth\", st[loop_depth] + 1)", "                    list fibody = parse_block(st, FALSE)", "                    st.add(\"loop_depth\", st[loop_depth] - 1)", "                    flint rj = 0", "                    while rj < len(fnames_k):", "                        dict fvars2 = st[vars]", "                        fvars2.remove(fnames_k[rj])", "                        rj += 1", "                    node = {k: \"for_in\", names: fnames_k, lnames: fnames_l, coll: coll, body: fibody, block_stmt: TRUE, line: ftok[line], col: ftok[col]}", "                    block_stmt = TRUE", "                else:", "                    if len(nts) != 1:", "                        fail(st, nts[1], \"SYNTAX_ERROR\", \"one loop variable for a numeric range\", \"two variables\")", "                        return stmts", "                    dict rnt = nts[0]", "                    str rname = rnt[value]", "                    if is_const_name(rname):", "                        fail(st, rnt, \"CONST_ERROR\", \"variable\", cat([\"constant '\", rname, \"'\"]))", "                        return stmts", "                    if is_reserved(rname):", "                        fail(st, rnt, \"NAME_ERROR\", \"free name\", cat([\"reserved '\", rname, \"'\"]))", "                        return stmts", "                    dict rvars = st[vars]", "                    dict rfor = st[for_names]", "                    dict rgv = st[gvars]", "                    if rvars.contains(rname) OR rfor.contains(rname) OR rgv.contains(rname):", "                        fail(st, rnt, \"REDECLARE_ERROR\", \"unique loop variable\", cat([\"name '\", rname, \"' is already declared\"]))", "                        return stmts", "                    rvars.add(rname, \"flint\")", "                    rfor.add(rname, TRUE)", "                    str rlua = mangle_var(st, rname)", "                    dict first = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    if NOT is_numeric(first[t]):", "                        fail(st, first, \"TYPE_ERROR\", \"loop bound to be flint\", first[t])", "                        return stmts", "                    dict ftnode = {k: \"for\", name: rname, lua: rlua, line: ftok[line], col: ftok[col]}", "                    if tok_is(tk(st), \"op\", \"..