ion at top level\", \"nested function\")", "                    return stmts", "                dict fntok = expect_tok(st, \"name\", \"\", \"function name\")", "                str fn_name = fntok[value]", "                if is_reserved(fn_name):", "                    fail(st, fntok, \"NAME_ERROR\", \"free name\", cat([\"reserved '\", fn_name, \"'\"]))", "                    return stmts", "                if is_const_name(fn_name):", "                    fail(st, fntok, \"CONST_ERROR\", \"function name\", cat([\"constant '\", fn_name, \"'\"]))", "                    return stmts", "                dict gvars = st[vars]", "                dict gfuncs = st[funcs]", "                if gfuncs.contains(fn_name) OR gvars.contains(fn_name):", "                    fail(st, fntok, \"REDECLARE_ERROR\", \"unique name\", cat([\"name '\", fn_name, \"' is already declared\"]))", "                    return stmts", "                expect_tok(st, \"op\", \"(\", \"'('\")", "                list params = []", "                if NOT tok_is(tk(st), \"op\", \")\"):", "                    while TRUE:", "                        dict pty_tok = tk(st)", "                        str pty = parse_type_name(st)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        if pty == \"NONE\":", "                            fail(st, pty_tok, \"TYPE_ERROR\", \"parameter type\", \"NONE\")", "                            return stmts", "                        dict pn = expect_tok(st, \"name\", \"\", \"parameter name\")", "                        str pnm = pn[value]", "                        if is_reserved(pnm):", "                            fail(st, pn, \"NAME_ERROR\", \"free name\", cat([\"reserved '\", pnm, \"'\"]))", "                            return stmts", "                        dict pgv = st[vars]", "                        if pgv.contains(pnm):", "                            fail(st, pn, \"REDECLARE_ERROR\", \"parameter name\", cat([\"global '\", pnm, \"' is already declared\"]))", "                            return stmts", "                        flint di = 0", "                        while di < len(params):", "                            dict pp0 = params[di]", "                            if pp0[name] == pnm:", "                                fail(st, pn, \"REDECLARE_ERROR\", \"unique parameter name\", cat([\"duplicate '\", pnm, \"'\"]))", "                                return stmts", "                            di += 1", "                        params.add({name: pnm, type: pty, line: pn[line], col: pn[col]})", "                        if tok_is(tk(st), \"op\", \",\"):", "                            advance(st)", "                        else:", "                            break", "                expect_tok(st, \"op\", \")\", \"')'\")", "                str fret = \"NONE\"", "                bool fhas_ret = FALSE", "                if tok_is(tk(st), \"op\", \"->\"):", "                    advance(st)", "                    dict rtok = tk(st)", "                    fret = parse_type_name(st)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    if fret == \"NONE\":", "                        fail(st, rtok, \"SYNTAX_ERROR\", \"return type (omit '->' for NONE)\", \"NONE\")", "                        return stmts", "                    fhas_ret = TRUE", "                expect_tok(st, \"op\", \":\", \"':'\")", "                dict fninfo = {params: params, ret: NONE, ret_nullable: FALSE, inferring: TRUE}", "                if fhas_ret:", "                    fninfo.add(\"ret\", fret)", "                gfuncs.add(fn_name, fninfo)", "                str flua = mangle_func(st, fn_name)", "                dict sv_vars = st[vars]", "                dict sv_nullable = st[nullable]", "                dict sv_maybe = st[maybe_unset]", "                dict sv_for = st[for_names]", "                dict sv_gvars = st[gvars]", "                dict sv_gnullable = st[gnullable]", "                dict sv_gmaybe = st[gmaybe]", "                flint sv_loop = st[loop_depth]", "                bool sv_in = st[in_func]", "                str sv_ret = st[func_ret]", "                list sv_returns = st[func_returns]", "                st.add(\"gvars\", st[vars])", "                st.add(\"gnullable\", st[nullable])", "                st.add(\"gmaybe\", st[maybe_unset])", "                st.add(\"vars\", {})", "                st.add(\"nullable\", {})", "                st.add(\"maybe_unset\", {})", "                st.add(\"for_names\", {})", "                st.add(\"loop_depth\", 0)", "                st.add(\"in_func\", TRUE)", "                st.add(\"func_ret\", fret)", "                st.add(\"func_returns\", [])", "                flint pj = 0", "                while pj < len(params):", "                    dict pj_p = params[pj]", "                    pj_p.add(\"lua\", mangle_var(st, pj_p[name]))", "                    dict nv = st[vars]", "                    nv.add(pj_p[name], pj_p[type])", "                    pj += 1", "                list fnbody = parse_block(st, FALSE)", "                list frets = st[func_returns]", "                st.add(\"vars\", sv_vars)", "                st.add(\"nullable\", sv_nullable)", "                st.add(\"maybe_unset\", sv_maybe)", "                st.add(\"for_names\", sv_for)", "                st.add(\"gvars\", sv_gvars)", "                st.add(\"gnullable\", sv_gnullable)", "                st.add(\"gmaybe\", sv_gmaybe)", "                st.add(\"loop_depth\", sv_loop)", "                st.add(\"in_func\", sv_in)", "                st.add(\"func_ret\", sv_ret)", "                st.add(\"func_returns\", sv_returns)", "                bool fallthrough = TRUE", "                if len(fnbody) > 0:", "                    dict last_stmt = fnbody[len(fnbody) - 1]", "                    if last_stmt[k] == \"return\":", "                        fallthrough = FALSE", "                bool fnullable = fallthrough", "                str seen = \"\"", "                flint ri = 0", "                while ri < len(frets):", "                    dict rr = frets[ri]", "                    if rr[empty] OR rr[type] == \"NONE\" OR e_nullable(rr):", "                        fnullable = TRUE", "                    elif fhas_ret:", "                        if rr[type] != fret AND rr[type] != \"any\":", "                            fail(st, rr, \"TYPE_ERROR\", cat([\"return type \", fret]), rr[type])", "                            return stmts", "                    else:", "                        if seen != \"\" AND seen != rr[type]:", "                            fail(st, rr, \"TYPE_ERROR\", cat([\"all returns of '\", fn_name, \"' to have one type\"]), cat([seen, \" and \", rr[type]]))", "                            return stmts", "                        seen = rr[type]", "                    ri += 1", "                str final_ret = fret", "                if NOT fhas_ret:", "                    final_ret = seen", "                    if final_ret == \"\":", "                        final_ret = \"NONE\"", "                fninfo.add(\"ret\", final_ret)", "                fninfo.add(\"ret_nullable\", fnullable)", "                fninfo.add(\"inferring\", FALSE)", "                node = {k: \"func\", name: fn_name, lua: flua, params: params, ret: final_ret, body: fnbody, block_stmt: TRUE, line: funtok[line], col: funtok[col]}", "                block_stmt = TRUE", "            elif t[type] == \"kw\" AND t[value] == \"model\":", "                dict mtok = advance(st)", "                if st[in_func] OR st[block_depth] > 0:", "                    fail(st, mtok, \"SCOPE_ERROR\", \"model at top level\", \"nested model\")", "                    return stmts", "                dict mnt = expect_tok(st, \"name\", \"\", \"model name\")", "                if NOT (st[err] is NONE):", "                    return stmts", "                str mname = mnt[value]", "                if is_reserved(mname) OR is_const_name(mname):", "                    fail(st, mnt, \"NAME_ERROR\", \"free model name\", cat([\"reserved '\", mname, \"'\"]))", "                    return stmts", "                dict mall = st[models]", "                dict mgv = st[vars]", "                dict mfnc = st[funcs]", "                if mall.contains(mname) OR mgv.contains(mname) OR mfnc.contains(mname):", "                    fail(st, mnt, \"REDECLARE_ERROR\", \"unique model name\", cat([\"name '\", mname, \"' is already declared\"]))", "                    return stmts", "                dict mschema = {name: mname, model_fields: {}, field_types: {}, consts: {}, init_fields: {}, params: [], param_types: {}, methods: {}, method_order: [], ctor: NONE, order: [], field_order: []}", "                mall.add(mname, mschema)", "                expect_tok(st, \"op\", \":\", \"':'\")", "                expect_tok(st, \"newline\", \"\", \"end of line after ':'\")", "                expect_tok(st, \"indent\", \"\", \"indented block\")", "                if NOT (st[err] is NONE):", "                    return stmts", "                list mfield_nodes = []", "                bool mseen_construct = FALSE", "                bool mseen_method = FALSE", "                bool mgoing = TRUE", "                while mgoing:", "                    dict mbt = tk(st)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    if mbt[type] == \"dedent\" OR mbt[type] == \"eof\":", "                        mgoing = FALSE", "                    elif mbt[type] == \"newline\":", "                        advance(st)", "                    elif mbt[type] == \"kw\" AND mbt[value] == \"construct\":", "                        if mseen_construct:", "                            fail(st, mbt, \"REDECLARE_ERROR\", \"one construct per model\", \"second construct\")", "                            return stmts", "                        if mseen_method:", "                            fail(st, mbt, \"SYNTAX_ERROR\", \"construct before methods\", \"construct after method\")", "                            return stmts", "                        dict mch = parse_construct_header(st, mschema)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        list mparams = mch[params]", "                        dict mctx = mch[mctx]", "                        dict sv = snapshot_parser(st)", "                        st.add(\"gvars\", st[vars])", "                        st.add(\"gnullable\", st[nullable])", "                        st.add(\"gmaybe\", st[maybe_unset])", "                        st.add(\"vars\", {})", "                        st.add(\"nullable\", {})", "                        st.add(\"maybe_unset\", {})", "                        st.add(\"for_names\", {})", "                        st.add(\"loop_depth\", 0)", "                        st.add(\"in_func\", TRUE)", "                        st.add(\"func_ret\", \"NONE\")", "                        st.add(\"func_returns\", [])", "                        st.add(\"model_ctx\", mctx)", "                        for p0 in mparams:", "                            dict p = p0", "                            p.add(\"lua\", mangle_var(st, p[name]))", "                            dict pv = st[vars]", "                            pv.add(p[name], p[type])", "                        list mbody = parse_block(st, FALSE)", "                        restore_parser(st, sv)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        if NOT mctx[self_seen]:", "                            fail(st, mtok, \"SYNTAX_ERROR\", \"self(...) as the first statement of construct\", \"missing self(...)\")", "                            return stmts", "                        dict mcons = mschema[ctor]", "                        mcons.add(\"body\", mbody)", "                        mseen_construct = TRUE", "                    elif mbt[type] == \"kw\" AND mbt[value] == \"method\":", "                        if NOT mseen_construct:", "                            fail(st, mbt, \"SYNTAX_ERROR\", \"construct before methods\", \"method before construct\")", "                            return stmts", "                        dict mmh = parse_method_header(st, mschema)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        dict mctx2 = {model_name: mname, schema: mschema, in_construct: FALSE, level: 0, self_seen: TRUE, self_done: TRUE, param_set: {}}", "                        dict sv2 = snapshot_parser(st)", "                        st.add(\"gvars\", st[vars])", "                        st.add(\"gnullable\", st[nullable])", "                        st.add(\"gmaybe\", st[maybe_unset])", "                        st.add(\"vars\", {})", "                        st.add(\"nullable\", {})", "                        st.add(\"maybe_unset\", {})", "                        st.add(\"for_names\", {})", "                        st.add(\"loop_depth\", 0)", "                        st.add(\"in_func\", TRUE)", "                        st.add(\"func_ret\", mmh[ret])", "                        st.add(\"func_returns\", [])", "                        st.add(\"model_ctx\", mctx2)", "                        list mparams2 = mmh[params]", "                        for p3 in mparams2:", "                            dict p3d = p3", "                            p3d.add(\"lua\", mangle_var(st, p3d[name]))", "                            dict pv2 = st[vars]", "                            pv2.add(p3d[name], p3d[type])", "                        list mbody2 = parse_block(st, FALSE)", "                        list mrets = st[func_returns]", "                        restore_parser(st, sv2)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        finish_method(st, mmh[info], mbody2, mmh[ret], mmh[has_ret], mrets)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        mseen_method = TRUE", "                    elif mbt[type] == \"kw\" AND is_scalar_type(mbt[value]):", "                        if mseen_construct OR mseen_method:", "                            fail(st, mbt, \"SYNTAX_ERROR\", \"model fields before construct\", \"field after construct\")", "                            return stmts", "                        dict mfnode = parse_model_field_decl(st, mschema)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        mfield_nodes.add(mfnode)", "                        dict mfnx = tk(st)", "                        if mfnx[type] == \"newline\":", "                            advance(st)", "                        elif mfnx[type] != \"dedent\":", "                            fail(st, mfnx, \"SYNTAX_ERROR\", \"end of line\", describe_tok(mfnx))", "                            return stmts", "                    else:", "                        fail(st, mbt, \"SYNTAX_ERROR\", \"model field, construct or method\", describe_tok(mbt))", "                        return stmts", "                if tk(st)[type] == \"dedent\":", "                    advance(st)", "                if NOT mseen_construct:", "                    fail(st, mtok, \"SYNTAX_ERROR\", \"construct in model\", \"missing construct\")", "                    return stmts", "                node = {k: \"model\", name: mname, schema: mschema, fields: mfield_nodes, line: mtok[line], col: mtok[col]}", "                block_stmt = TRUE", "            elif t[type] == \"kw\" AND t[value] == \"return\":", "                dict rtok2 = advance(st)", "                if NOT st[in_func]:", "                    fail(st, rtok2, \"SCOPE_ERROR\", \"'return' inside a function\", \"'return' at top level\")", "                    return stmts", "                dict rexpr = {}", "                bool has_expr = FALSE", "                if tok_is(tk(st), \"op\", \":\"):", "                    advance(st)", "                else:", "                    rexpr = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    has_expr = TRUE", "                list cur_rets = st[func_returns]", "                if has_expr:", "                    cur_rets.add({empty: FALSE, type: rexpr[t], nullable: e_nullable(rexpr), line: rtok2[line], col: rtok2[col]})", "                    node = {k: \"return\", expr: rexpr, line: rtok2[line], col: rtok2[col]}", "                else:", "                    cur_rets.add({empty: TRUE, type: \"NONE\", nullable: FALSE, line: rtok2[line], col: rtok2[col]})", "                    node = {k: \"return\", line: rtok2[line], col: rtok2[col]}", "            elif t[type] == \"kw\" AND (t[value] == \"break\" OR t[value] == \"continue\"):", "                dict btok = advance(st)", "                if st[loop_depth] == 0:", "                    fail(st, btok, \"SCOPE_ERROR\", \"'break' or 'continue' inside a loop\", cat([\"'\", btok[value], \"' outside a loop\"]))", "                    return stmts", "                if try_crosses_loop(st):", "                    fail(st, btok, \"SCOPE_ERROR\", \"'break' or 'continue' inside the loop that contains try\", cat([\"'\", btok[value], \"' across a try boundary\"]))", "                    return stmts", "                node = {k: btok[value], line: btok[line], col: btok[col]}", "            elif t[type] == \"name\" AND NOT is_template_func(t[value]) AND peek_value(st) == \"=\":", "                dict atok = advance(st)", "                str aname = atok[value]", "                dict aw = resolve_write(st, atok, aname)", "                if NOT (st[err] is NONE):", "                    return stmts", "                advance(st)", "                dict aexpr = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return stmts", "                str avt = aw[type]", "                if NOT assignable(aexpr[t], avt):", "                    fail(st, {line: aexpr[line], col: aexpr[col]}, \"TYPE_ERROR\", cat([\"assignment to '\", aname, \"': type \", avt]), aexpr[t])", "                    return stmts", "                dict anl = st[nullable]", "                if aw[kind] == \"global\":", "                    anl = st[gnullable]", "                if aexpr[t] == \"NONE\" OR e_nullable(aexpr):", "                    anl.add(aname, TRUE)", "                else:", "                    anl.remove(aname)", "                node = {k: \"assign\", name: aname, lua: aw[lua], expr: aexpr, type: avt, line: atok[line], col: atok[col]}", "            elif t[type] == \"name\" AND NOT is_template_func(t[value]) AND is_compound(peek_value(st)):", "                dict ctok = advance(st)", "                str cname = ctok[value]", "                dict cw = resolve_write(st, ctok, cname)", "                if NOT (st[err] is NONE):", "                    return stmts", "                dict cop_tok = advance(st)", "                str cop_full = cop_tok[value]", "                str cop = cop_full[..len(cop_full) - 1]", "                dict cexpr = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return stmts", "                str cvt = cw[type]", "                if cvt != \"flint\" OR NOT is_numeric(cexpr[t]):", "                    fail(st, cop_tok, \"TYPE_ERROR\", cat([\"numeric operands of '\", cop_full, \"'\"]), cexpr[t])", "                    return stmts", "                bool cmaybe = FALSE", "                if cw[kind] == \"global\":", "                    dict cgnl = st[gnullable]", "                    dict cgmu = st[gmaybe]", "                    if cgnl.contains(cname):", "                        cmaybe = TRUE", "                    if cgmu.contains(cname):", "                        cmaybe = TRUE", "                    cgnl.remove(cname)", "                else:", "                    dict cnl = st[nullable]", "                    dict cmu = st[maybe_unset]", "                    if cnl.contains(cname):", "                        cmaybe = TRUE", "                    if cmu.contains(cname):", "                        cmaybe = TRUE", "                    cnl.remove(cname)", "                node = {k: \"compound\", name: cname, lua: cw[lua], op: cop, expr: cexpr, nullable: cmaybe, line: ctok[line], col: ctok[col]}", "            else:", "                dict e = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return stmts", "                if e[k] == \"self_init\":", "                    dict sctx = st[model_ctx]", "                    if sctx is NONE OR NOT sctx[in_construct]:", "                        fail(st, e, \"SCOPE_ERROR\", \"self(...) in construct\", \"self(...) outside construct\")", "                        return stmts", "                    if st[block_depth] != sctx[level] OR len(stmts) != 0:", "                        fail(st, e, \"SYNTAX_ERROR\", \"self(...) as the first statement of construct\", \"nested or later self(...)\")", "                        return stmts", "                    if sctx[self_seen]:", "                        fail(st, e, \"REDECLARE_ERROR\", \"one self(...) per construct\", \"second self(...)\")", "                        return stmts", "                    list sargs = e[names]", "                    dict ssch = sctx[schema]", "                    dict scons = ssch[ctor]", "                    list sps = []", "                    if NOT (scons is NONE):", "                        sps = scons[params]", "                    flint slast = -1", "                    list sfields = []", "                    flint si = 0", "                    while si < len(sargs):", "                        dict sat = sargs[si]", "                        str san = sat[value]", "                        flint sfound = -1", "                        flint sj = 0", "                        while sj < len(sps):", "                            dict ssp = sps[sj]", "                            if ssp[name] == san:", "                                sfound = sj", "                            sj += 1", "                        if sfound < 0:", "                            fail(st, sat, \"NAME_ERROR\", \"construct parameter in self(...)\", cat([\"unknown '\", san, \"'\"]))", "                            return stmts", "                        if sfound <= slast:", "                            fail(st, sat, \"SYNTAX_ERROR\", \"construct parameters in declaration order\", cat([\"out of order '\", san, \"'\"]))", "                            return stmts", "                        slast = sfound", "                        dict sp = sps[sfound]", "                        add_model_field(st, sctx[schema], sat, san, sp[type], FALSE)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        sfields.add({name: san, type: sp[type], lua: sp[lua], line: sat[line], col: sat[col]})", "                        si += 1", "                    sctx.add(\"self_seen\", TRUE)", "                    sctx.add(\"self_done\", TRUE)", "                    node = {k: \"self_init\", fields: sfields, line: e[line], col: e[col]}", "                elif tok_is(tk(st), \"op\", \"=\"):", "                    str ek = e[k]", "                    if ek == \"field\":", "                        dict fb = e[base]", "                        dict fschema = model_schema(st, e[mname])", "                        str fld = e[name]", "                        dict mctx6 = st[model_ctx]", "                        bool in_con = FALSE", "                        if NOT (mctx6 is NONE) AND mctx6[in_construct] AND fb[k] == \"var\" AND fb[name] == \"self\":", "                            if st[block_depth] == mctx6[level]:", "                                in_con = TRUE", "                        if e[model_field]:", "                            fail(st, e, \"CONST_ERROR\", \"mutable field\", cat([\"model field '\", fld, \"' is read-only\"]))", "                            return stmts", "                        if e[is_const]:", "                            fail(st, e, \"CONST_ERROR\", \"mutable field\", cat([\"constant '\", fld, \"' is read-only\"]))", "                            return stmts", "                        dict ftypes6 = fschema[field_types]", "                        if NOT ftypes6.contains(fld):", "                            if NOT in_con OR NOT mctx6[self_done]:", "                                fail(st, e, \"NAME_ERROR\", cat([\"declared field of '\", e[mname], \"'\"]), cat([\"unknown '\", fld, \"'\"]))", "                                return stmts", "                            dict mctx6ps = mctx6[param_set]", "                            if mctx6ps.contains(fld):", "                                fail(st, e, \"REDECLARE_ERROR\", \"new field name\", cat([\"construct parameter '\", fld, \"'\"]))", "                                return stmts", "                            dict mcvar = st[vars]", "                            if mcvar.contains(fld):", "                                fail(st, e, \"REDECLARE_ERROR\", \"new field name\", cat([\"local '\", fld, \"'\"]))", "                                return stmts", "                        dict eq = advance(st)", "                        dict fexpr = parse_expr(st, 0)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        str fexpty = fexpr[t]", "                        if ftypes6.contains(fld):", "                            if NOT assignable(fexpty, ftypes6.take(fld)):", "                                fail(st, {line: fexpr[line], col: fexpr[col]}, \"TYPE_ERROR\", cat([\"field '\", fld, \"': type \", ftypes6.take(fld)]), fexpty)", "                                return stmts", "                            node = {k: \"field_assign\", base: fb, mname: e[mname], name: fld, expr: fexpr, type: ftypes6.take(fld), line: eq[line], col: eq[col]}", "                        else:", "                            if NOT is_scalar_type(fexpty):", "                                fail(st, {line: fexpr[line], col: fexpr[col]}, \"TYPE_ERROR\", \"scalar instance field (str, flint, bool)\", fexpty)", "                                return stmts", "                            add_model_field(st, fschema, e, fld, fexpty, TRUE)", "                            if NOT (st[err] is NONE):", "                                return stmts", "                            node = {k: \"field_create\", base: fb, mname: e[mname], name: fld, expr: fexpr, type: fexpty, line: eq[line], col: eq[col]}", "                    else:", "                        if ek != \"index\" AND ek != \"dget\":", "                            fail(st, {line: e[line], col: e[col]}, \"TYPE_ERROR\", \"variable, field or index as assignment target\", ek)", "                            return stmts", "                        if ek == \"index\":", "                            dict seb = e[base]", "                            if seb[t] == \"str\":", "                                fail(st, {line: e[line], col: e[col]}, \"TYPE_ERROR\", \"mutable index target\", \"str is immutable\")", "                                return stmts", "                        dict eq2 = advance(st)", "                        dict eval2 = parse_expr(st, 0)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        node = {k: \"setindex\", target: e, expr: eval2, line: eq2[line], col: eq2[col]}", "                else:", "                    node = {k: \"exprstmt\", expr: e, line: e[line], col: e[col]}", "            if NOT decl_block:", "                stmts.add(node)", "                if NOT block_stmt:", "                    dict nx2 = tk(st)", "                    if top:", "                        if nx2[type] == \"newline\":", "                            advance(st)", "                        elif nx2[type] != \"eof\":", "                            fail(st, nx2, \"SYNTAX_ERROR\", \"end of line\", describe_tok(nx2))", "                            return stmts", "                    else:", "                        if nx2[type] == \"newline\":", "                            advance(st)", "                        elif nx2[type] != \"dedent\":", "                            fail(st, nx2, \"SYNTAX_ERROR\", \"end of line\", describe_tok(nx2))", "                            return stmts", "    if NOT top:", "        if tk(st)[type] == \"dedent\":", "            advance(st)", "        st.add(\"block_depth\", st[block_depth] - 1)", "    return stmts", "", "# ---------- кодогенератор ----------", "", "func wrap_flint(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_flint(\", x, \")\"])", "    return x", "", "func wrap_str(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_str(\", x, \")\"])", "    return x", "", "func wrap_list(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_list(\", x, \")\"])", "    return x", "", "func wrap_dict(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_dict(\", x, \")\"])", "    return x", "", "func wrap_froz(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_froz(\", x, \")\"])", "    return x", "", "func wrap_bool(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_bool(\", x, \")\"])", "    return x", "", "# Приводит значение к базовому типу назначения; параметры типа проверяет рантайм.", "func as_base(str x, str target) -> str:", "    str b = base_type(target)", "    if b == \"flint\":", "        return cat([\"krt.as_flint(\", x, \")\"])", "    if b == \"str\":", "        return cat([\"krt.as_str(\", x, \")\"])", "    if b == \"bool\":", "        return cat([\"krt.as_bool(\", x, \")\"])", "    if b == \"list\":", "        return cat([\"krt.as_list(\", x, \")\"])", "    if b == \"froz\":", "        return cat([\"krt.as_froz(\", x, \")\"])", "    if b == \"dict\":", "        return cat([\"krt.as_dict(\", x, \")\"])", "    return cat([\"krt.as_model(\", x, lua_str(target), \")\"])", "", "# Присоединяет спецификацию параметризованного типа к коллекции.", "func typed_wrap(str x, str target) -> str:", "    if NOT is_typed_spec(target):", "        return x", "    str b = base_type(target)", "    if b == \"list\":", "        return cat([\"krt.typed_list(\", lua_str(target), \", \", x, \")\"])", "    if b == \"froz\":", "        return cat([\"krt.typed_froz(\", lua_str(target), \", \", x, \")\"])", "    if b == \"dict\":", "        return cat([\"krt.typed_dict(\", lua_str(target), \", \", x, \")\"])", "    return x", "", "func checked(str x, str ety, bool nullable, str target) -> str:", "    if ety == \"any\" AND NOT nullable:", "        return as_base(x, target)", "    return x", "", "func wrap_to(str x, str ety, bool nullable, str target) -> str:", "    if ety == \"NONE\" OR ety == \"any\" OR nullable:", "        return as_base(x, target)", "    return x", "", "func ordered_x(str x, dict e, dict other) -> str:", "    if e[t] == \"NONE\" OR e_nullable(e):", "        str ty = e[t]", "        if ty == \"NONE\":", "            ty = other[t]", "        if ty == \"str\":", "            return cat([\"krt.as_str(\", x, \")\"])", "        return cat([\"krt.as_flint(\", x, \")\"])", "    return x", "", "func emit_line(dict st, str s):", "    if NOT (st[cur_pos] is NONE):", "        dict cp = st[cur_pos]", "        if len(cp) > 0:", "            list lm = st[line_map]", "            lm.add({gen: len(st[out]) + 1, line: cp[line], col: cp[col]})", "    list o = st[out]", "    o.add(cat([spaces(st[indent] * 4), s]))", "", "func stmt_pos(dict s) -> dict:", "    str sk = s[k]", "    if sk == \"panic\":", "        return {line: s[line], col: s[col]}", "    if sk == \"decl\" OR sk == \"assign\" OR sk == \"compound\" OR sk == \"exprstmt\" OR sk == \"return\":", "        if s.contains(\"expr\"):", "            dict e = s[expr]", "            return {line: e[line], col: e[col]}", "    if sk == \"if\":", "        list brs = s[branches]", "        dict b0 = brs[0]", "        dict c0 = b0[cond]", "        return {line: c0[line], col: c0[col]}", "    if sk == \"while\":", "        dict wc = s[cond]", "        return {line: wc[line], col: wc[col]}", "    if sk == \"for\":", "        if s.contains(\"from\"):", "            dict fe = s[from]", "            return {line: fe[line], col: fe[col]}", "        dict te = s[to]", "        return {line: te[line], col: te[col]}", "    if sk == \"for_in\":", "        dict cc = s[coll]", "        return {line: cc[line], col: cc[col]}", "    return {line: s[line], col: s[col]}", "", "# Выражение -> текст Lua. Рекурсивна только сама в себя.", "func emit_expr(dict st, dict e) -> str:", "    str k = e[k]", "", "    if k == \"num\":", "        return cat([\"(\", str(e[value]), \")\"])", "    if k == \"bool\":", "        if e[value]:", "            return \"true\"", "        return \"false\"", "    if k == \"none\":", "        return \"krt.NONE\"", "    if k == \"var\":", "        return e[lua]", "", "    if k == \"model_field\":", "        return cat([\"krt.model_get(self, \", lua_str(e[name]), \")\"])", "    if k == \"field\":", "        return cat([\"krt.model_get(\", emit_expr(st, e[base]), \", \", lua_str(e[name]), \")\"])", "    if k == \"model_new\":", "        list mna = e[args]", "        list mnp = [lua_str(e[mname])]", "        flint mni = 0", "        while mni < len(mna):", "            dict mnarg = mna[mni]", "            mnp.add(emit_expr(st, mnarg))", "            mni += 1", "        return cat([\"krt.model_new(\", mnp.join(\", \"), \")\"])", "    if k == \"model_init\":", "        list mia = e[args]", "        list mip = []", "        for mia0 in mia:", "            dict mian = mia0", "            mip.add(cat([\"[\", lua_str(mian[name]), \"] = \", emit_expr(st, mian[expr])]))", "        return cat([\"krt.model_init(\", lua_str(e[mname]), \", \\{\", mip.join(\", \"), \"\\})\"])", "    if k == \"model_method\":", "        list mma2 = e[args]", "        list mmp2 = [emit_expr(st, e[base]), lua_str(e[name])]", "        list mmpt2 = e[ptypes]", "        flint mmi2 = 0", "        while mmi2 < len(mma2):", "            dict mmarg = mma2[mmi2]", "            str mmtgt = mmpt2[mmi2]", "            mmp2.add(wrap_to(emit_expr(st, mmarg), mmarg[t], e_nullable(mmarg), mmtgt))", "            mmi2 += 1", "        return cat([\"krt.model_call(\", mmp2.join(\", \"), \")\"])", "    if k == \"self_init\":", "        return \"krt.NONE\"", "", "    if k == \"func_ref\":", "        return e[lua]", "", "    if k == \"str\" OR k == \"call\":", "        list parts = e[parts]", "        list pieces = []", "        for p0 in parts:", "            dict p = p0", "            if p[kind] == \"text\":", "                pieces.add(lua_str(p[value]))", "            else:", "                dict pe = p[expr]", "                pieces.add(cat([\"krt.tostr(\", emit_expr(st, pe), \")\"]))", "        str body = \"\\\"\\\"\"", "        if len(pieces) == 1:", "            body = pieces[0]", "        elif len(pieces) > 1:", "            body = cat([\"(\", pieces.join(\" .. \"), \")\"])", "        if k == \"str\":", "            return body", "        str f = e[fn]", "        if f == \"show\":", "            return cat([\"krt.show(\", body, \")\"])", "        if f == \"show_err\":", "            return cat([\"krt.show_err(\", body, \")\"])", "        return cat([\"krt.input(\", body, \")\"])", "", "    if k == \"builtin\":", "        str bn = e[name]", "        list ba = e[args]", "        if bn == \"args\":", "            return \"krt.args()\"", "        if bn == \"time_ms\":", "            return \"krt.time_ms()\"", "        if bn == \"is_tty\":", "            return \"krt.is_tty()\"", "        dict a0 = ba[0]", "        if bn == \"len\":", "            return cat([\"krt.len(\", emit_expr(st, a0), \")\"])", "        if bn == \"type\":", "            return cat([\"krt.typeof(\", emit_expr(st, a0), \")\"])", "        if bn == \"str\":", "            return cat([\"krt.tostr(\", emit_expr(st, a0), \")\"])", "        if bn == \"flint\":", "            return cat([\"krt.to_flint(\", emit_expr(st, a0), \")\"])", "        if bn == \"up\":", "            return cat([\"krt.str_up(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"low\":", "            return cat([\"krt.str_low(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"title\":", "            return cat([\"krt.str_title(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"abs\":", "            return cat([\"krt.num_abs(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"round\":", "            return cat([\"krt.num_round(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"floor\":", "            return cat([\"krt.num_floor(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"ceil\":", "            return cat([\"krt.num_ceil(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"sqrt\":", "            return cat([\"krt.num_sqrt(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"min\" OR bn == \"max\":", "            list mvals = []", "            for mn0 in ba:", "                dict mnode = mn0", "                if base_type(mnode[t]) == \"list\":", "                    mvals.add(wrap_list(emit_expr(st, mnode), mnode[t], e_nullable(mnode)))", "                else:", "                    mvals.add(wrap_flint(emit_expr(st, mnode), mnode[t], e_nullable(mnode)))", "            return cat([\"krt.num_\", bn, \"(\", mvals.join(\", \"), \")\"])", "        if bn == \"sum\":", "            return cat([\"krt.coll_sum(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"avg\":", "            return cat([\"krt.coll_avg(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"keys\":", "            return cat([\"krt.coll_keys(\", wrap_dict(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"values\":", "            return cat([\"krt.coll_values(\", wrap_dict(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"upk\":", "            if base_type(a0[t]) == \"dict\":", "                return cat([\"krt.coll_upk(\", wrap_dict(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "            return cat([\"krt.coll_upk(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"sort\":", "            return cat([\"krt.coll_sort(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"reverse\":", "            return cat([\"krt.coll_reverse(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"clear\":", "            if base_type(a0[t]) == \"dict\":", "                return cat([\"krt.coll_clear(\", wrap_dict(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "            return cat([\"krt.coll_clear(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"map\" OR bn == \"filter\":", "            dict hf = ba[1]", "            return cat([\"krt.coll_\", bn, \"(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \", \", emit_expr(st, hf), \")\"])", "        if bn == \"reduce\":", "            dict rf = ba[1]", "            dict rs = ba[2]", "            return cat([\"krt.coll_reduce(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \", \", emit_expr(st, rf), \", \", emit_expr(st, rs), \")\"])", "        if bn == \"system\":", "            return cat([\"krt.system(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"assert\":", "            dict amsg = ba[1]", "            return cat([\"krt.do_assert_strict(\", emit_expr(st, a0), \", \", wrap_str(emit_expr(st, amsg), amsg[t], e_nullable(amsg)), \")\"])", "        if bn == \"expect\":", "            return cat([\"krt.expect_new(\", emit_expr(st, a0), \")\"])", "        if bn == \"read_file\":", "            return cat([\"krt.read_file(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"write_file\":", "            dict a1 = ba[1]", "            return cat([\"krt.write_file(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \", \", wrap_str(emit_expr(st, a1), a1[t], e_nullable(a1)), \")\"])", "        if bn == \"file_exists\":", "            return cat([\"krt.file_exists(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"exit\":", "            return cat([\"krt.exit(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        return \"krt.NONE\"", "", "    if k == \"call_user\":", "        list car = e[args]", "        list cp = []", "        list cpt = e[ptypes]", "        flint ci = 0", "        while ci < len(car):", "            dict cnode = car[ci]", "            str ctgt = cpt[ci]", "            str cx = emit_expr(st, cnode)", "            cp.add(wrap_to(cx, cnode[t], e_nullable(cnode), ctgt))", "            ci += 1", "        return cat([e[lua], \"(\", cp.join(\", \"), \")\"])", "", "    if k == \"list\":", "        list its = e[items]", "        list ip = []", "        for it0 in its:", "            dict itn = it0", "            ip.add(emit_expr(st, itn))", "        return cat([\"krt.list(\\{\", ip.join(\", \"), \"\\})\"])", "", "    if k == \"dict\":", "        list prs = e[pairs]", "        str dx = \"krt.dict()\"", "        for pd0 in prs:", "            dict pd = pd0", "            dict pv = pd[value]", "            dx = cat([\"krt.dict_set(\", dx, \", \", lua_str(pd[key]), \", \", emit_expr(st, pv), \")\"])", "        return dx", "", "    if k == \"dget\":", "        dict db = e[base]", "        return cat([\"krt.dict_get(\", wrap_dict(emit_expr(st, db), db[t], e_nullable(db)), \", \", lua_str(e[key]), \")\"])", "", "    if k == \"index\":", "        dict ib = e[base]", "        dict ii = e[index]", "        str ix = wrap_flint(emit_expr(st, ii), ii[t], e_nullable(ii))", "        str ibb = base_type(ib[t])", "        if ibb == \"list\":", "            return cat([\"krt.list_index(\", wrap_list(emit_expr(st, ib), ib[t], e_nullable(ib)), \", \", ix, \")\"])", "        if ibb == \"froz\":", "            return cat([\"krt.list_index(\", wrap_froz(emit_expr(st, ib), ib[t], e_nullable(ib)), \", \", ix, \")\"])", "        if ib[t] == \"any\":", "            return cat([\"krt.index(\", emit_expr(st, ib), \", \", ix, \")\"])", "        return cat([\"krt.str_index(\", wrap_str(emit_expr(st, ib), ib[t], e_nullable(ib)), \", \", ix, \")\"])", "", "    if k == \"slice\":", "        dict sb = e[base]", "        str sx = emit_expr(st, sb)", "        str sfn = \"str_slice\"", "        str recv = wrap_str(sx, sb[t], e_nullable(sb))", "        str sbb = base_type(sb[t])", "        if sbb == \"list\":", "            sfn = \"list_slice\"", "            recv = wrap_list(sx, sb[t], e_nullable(sb))", "        elif sbb == \"froz\":", "            sfn = \"list_slice\"", "            recv = wrap_froz(sx, sb[t], e_nullable(sb))", "        elif sb[t] == \"any\":", "            sfn = \"slice\"", "            recv = sx", "        list sp = [recv]", "        if e[from] is NONE:", "            sp.add(\"nil\")", "        else:", "            dict fr = e[from]", "            sp.add(wrap_flint(emit_expr(st, fr), fr[t], e_nullable(fr)))", "        if e[to] is NONE:", "            sp.add(\"nil\")", "        else:", "            dict tto = e[to]", "            sp.add(wrap_flint(emit_expr(st, tto), tto[t], e_nullable(tto)))", "        if NOT (e[step] is NONE):", "            dict stp = e[step]", "            sp.add(wrap_flint(emit_expr(st, stp), stp[t], e_nullable(stp)))", "        return cat([\"krt.\", sfn, \"(\", sp.join(\", \"), \")\"])", "", "    if k == \"method\":", "        dict mb = e[base]", "        str mx = emit_expr(st, mb)", "        str mrecv = wrap_str(mx, mb[t], e_nullable(mb))", "        str mbb = base_type(mb[t])", "        if mbb == \"list\":", "            mrecv = wrap_list(mx, mb[t], e_nullable(mb))", "        elif mbb == \"froz\":", "            mrecv = wrap_froz(mx, mb[t], e_nullable(mb))", "        elif mbb == \"dict\":", "            mrecv = wrap_dict(mx, mb[t], e_nullable(mb))", "        list mar = e[args]", "        list mp = [mrecv]", "        flint mi = 0", "        while mi < len(mar):", "            dict ma = mar[mi]", "            str mspec = e[a1]", "            if mi == 1:", "                mspec = e[a2]", "            str mxx = emit_expr(st, ma)", "            if mspec == \"str\":", "                mxx = wrap_str(mxx, ma[t], e_nullable(ma))", "            elif mspec == \"flint\":", "                mxx = wrap_flint(mxx, ma[t], e_nullable(ma))", "            elif mspec == \"dict\":", "                mxx = wrap_dict(mxx, ma[t], e_nullable(ma))", "            mp.add(mxx)", "            mi += 1", "        return cat([\"krt.\", e[rt], \"(\", mp.join(\", \"), \")\"])", "", "    if k == \"un\":", "        dict ua = e[a]", "        if e[op] == \"-\":", "            return cat([\"(-(\", wrap_flint(emit_expr(st, ua), ua[t], e_nullable(ua)), \"))\"])", "        return cat([\"(not krt.truthy_strict(\", emit_expr(st, ua), \"))\"])", "", "    if k == \"is\":", "        dict ia = e[a]", "        str ix2 = emit_expr(st, ia)", "        str ty2 = e[typename]", "        if ty2 == \"flint\":", "            return cat([\"(type(\", ix2, \") == \\\"number\\\")\"])", "        if ty2 == \"str\":", "            return cat([\"(type(\", ix2, \") == \\\"string\\\")\"])", "        if ty2 == \"bool\":", "            return cat([\"(type(\", ix2, \") == \\\"boolean\\\")\"])", "        str tyb = base_type(ty2)", "        if tyb == \"list\":", "            return cat([\"krt.is_list(\", ix2, \")\"])", "        if tyb == \"froz\":", "            return cat([\"krt.is_froz(\", ix2, \")\"])", "        if tyb == \"dict\":", "            return cat([\"krt.is_dict(\", ix2, \")\"])", "        if is_model_type(st, ty2):", "            return cat([\"krt.is_model(\", ix2, \", \", lua_str(ty2), \")\"])", "        return cat([\"(\", ix2, \" == krt.NONE or \", ix2, \" == nil)\"])", "", "    if k == \"bin\":", "        str op = e[op]", "        dict bna = e[a]", "        dict bnb = e[b]", "        str xa = emit_expr(st, bna)", "        str xb = emit_expr(st, bnb)", "        if op == \"+\":", "            return cat([\"(\", wrap_flint(xa, bna[t], e_nullable(bna)), \" + \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"-\":", "            return cat([\"(\", wrap_flint(xa, bna[t], e_nullable(bna)), \" - \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"*\":", "            return cat([\"(\", wrap_flint(xa, bna[t], e_nullable(bna)), \" * \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"/\":", "            return cat([\"krt.div(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"//\":", "            return cat([\"krt.idiv(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"%\":", "            return cat([\"krt.mod(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"**\":", "            return cat([\"krt.pow(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"==\":", "            return cat([\"(\", xa, \" == \", xb, \")\"])", "        if op == \"!=\":", "            return cat([\"(\", xa, \" ~= \", xb, \")\"])", "        if op == \"<\" OR op == \"<=\" OR op == \">\" OR op == \">=\":", "            if bna[t] == \"any\" OR bnb[t] == \"any\":", "                str cfn = \"lt\"", "                if op == \"<=\":", "                    cfn = \"le\"", "                elif op == \">\":", "                    cfn = \"gt\"", "                elif op == \">=\":", "                    cfn = \"ge\"", "                return cat([\"krt.\", cfn, \"(\", xa, \", \", xb, \")\"])", "            return cat([\"(\", ordered_x(xa, bna, bnb), \" \", op, \" \", ordered_x(xb, bnb, bna), \")\"])", "        if op == \"AND\":", "            return cat([\"(krt.truthy_strict(\", xa, \") and krt.truthy_strict(\", xb, \"))\"])", "        if op == \"OR\":", "            return cat([\"(krt.truthy_strict(\", xa, \") or krt.truthy_strict(\", xb, \"))\"])", "        return \"krt.NONE\"", "", "    if k == \"chain\":", "        list cops = e[ops]", "        list coper = e[operands]", "        list clines = []", "        list cconds = []", "        dict cprev_node = coper[0]", "        str cprev = emit_expr(st, cprev_node)", "        flint cj = 0", "        while cj < len(cops):", "            dict co = cops[cj]", "            dict crhs_node = coper[cj + 1]", "            str crhs = \"\"", "            if cj < len(cops) - 1:", "                crhs = cat([\"__t\", str(cj + 1)])", "                clines.add(cat([\"local \", crhs, \" = \", emit_expr(st, crhs_node)]))", "            else:", "                crhs = emit_expr(st, crhs_node)", "            str cl = cprev", "            str cr = crhs", "            str cop2 = co[op]", "            if cop2 == \"==\":", "                cconds.add(cat([\"(\", cl, \" == \", cr, \")\"]))", "            elif cop2 == \"!=\":", "                cconds.add(cat([\"(\", cl, \" ~= \", cr, \")\"]))", "            elif cprev_node[t] == \"any\" OR crhs_node[t] == \"any\":", "                str cfn2 = \"lt\"", "                if cop2 == \"<=\":", "                    cfn2 = \"le\"", "                elif cop2 == \">\":", "                    cfn2 = \"gt\"", "                elif cop2 == \">=\":", "                    cfn2 = \"ge\"", "                cconds.add(cat([\"krt.\", cfn2, \"(\", cl, \", \", cr, \")\"]))", "            else:", "                if cprev_node[t] == \"NONE\" OR e_nullable(cprev_node):", "                    if cprev_node[t] == \"str\":", "                        cl = cat([\"krt.as_str(\", cl, \")\"])", "                    else:", "                        cl = cat([\"krt.as_flint(\", cl, \")\"])", "                if crhs_node[t] == \"NONE\" OR e_nullable(crhs_node):", "                    if crhs_node[t] == \"str\":", "                        cr = cat([\"krt.as_str(\", cr, \")\"])", "                    else:", "                        cr = cat([\"krt.as_flint(\", cr, \")\"])", "                cconds.add(cat([\"(\", cl, \" \", cop2, \" \", cr, \")\"]))", "            cprev = crhs", "            cprev_node = crhs_node", "            cj += 1", "        str cpre = \"\"", "        if len(clines) > 0:", "            cpre = cat([clines.join(\"; \"), \"; \"])", "        return cat([\"(function() \", cpre, \"return \", cconds.join(\" and \"), \" end)()\"])", "", "    return \"krt.NONE\"", "", "# Объявления поднимаются в начало своей функции (D11, D43).", "func collect_walk(list stmts, list out) -> list:", "    for s0 in stmts:", "        dict s = s0", "        str sk = s[k]", "        if sk == \"decl\":", "            out.add(s[lua])", "        elif sk == \"if\":", "            list brs = s[branches]", "            for b0 in brs:", "                dict b = b0", "                collect_walk(b[body], out)", "            if s.contains(\"else_body\"):", "                collect_walk(s[else_body], out)", "        elif sk == \"while\" OR sk == \"for\" OR sk == \"for_in\":", "            collect_walk(s[body], out)", "        elif sk == \"try\":", "            collect_walk(s[body], out)", "            for h0 in s[triggers]:", "                dict h = h0", "                collect_walk(h[body], out)", "            if NOT (s[any] is NONE):", "                dict ha = s[any]", "                collect_walk(ha[body], out)", "            collect_walk(s[\"finally\"], out)", "    return out", "", "func collect_scope(list stmts) -> list:", "    list out = []", "    collect_walk(stmts, out)", "    return out", "", "func emit_hoist(dict st, list names):", "    if len(names) == 0:", "        return:", "    list lua = []", "    list nones = []", "    for n0 in names:", "        str n = n0", "        lua.add(n)", "        nones.add(\"krt.NONE\")", "    emit_line(st, cat([\"local \", lua.join(\", \"), \" = \", nones.join(\", \")]))", "", "func lua_str_map_keys(dict d, list ks) -> str:", "    list parts = []", "    for k in ks:", "        if d.contains(k):", "            parts.add(cat([\"[\", lua_str(k), \"] = \", lua_str(d.take(k))]))", "    if len(parts) == 0:", "        return \"\\{\\}\"", "    return cat([\"\\{\", parts.join(\", \"), \"\\}\"])", "", "func lua_true_map_keys(dict d, list ks) -> str:", "    list parts = []", "    for k in ks:", "        if d.contains(k):", "            parts.add(cat([\"[\", lua_str(k), \"] = true\"]))", "    if len(parts) == 0:", "        return \"\\{\\}\"", "    return cat([\"\\{\", parts.join(\", \"), \"\\}\"])", "", "func cat_lists(list a, list b) -> list:", "    list out = []", "    for x in a:", "        out.add(x)", "    for y in b:", "        out.add(y)", "    return out", "", "func lua_str_list(list xs) -> str:", "    list parts = []", "    for x in xs:", "        parts.add(lua_str(x))", "    return cat([\"\\{\", parts.join(\", \"), \"\\}\"])", "", "# Стейтменты -> строки Lua. Рекурсивна только сама в себя.", "func emit_stmts(dict st, list stmts) -> str:", "    flint i = 0", "    while i < len(stmts):", "        dict s = stmts[i]", "        dict saved = st[cur_pos]", "        st.add(\"cur_pos\", stmt_pos(s))", "        str sk = s[k]", "        bool wrap_ret = FALSE", "        if sk == \"return\" AND i < len(stmts) - 1:", "            wrap_ret = TRUE", "            emit_line(st, \"do\")", "            st.add(\"indent\", st[indent] + 1)", "        if sk == \"model\":", "            dict msc = s[schema]", "            str mn2 = s[name]", "            dict msc_mf = msc[model_fields]", "            dict msc_ft = msc[field_types]", "            dict msc_cs = msc[consts]", "            dict msc_if = msc[init_fields]", "            dict msc_pt = msc[param_types]", "            list msc_ord = msc[order]", "            list msc_fo = msc[field_order]", "            list msc_pl = msc[params]", "            list msc_all = msc_fo", "            emit_line(st, cat([\"krt.model_define(\", lua_str(mn2), \", \", lua_str_map_keys(msc_mf, msc_ord), \", \", lua_str_map_keys(msc_ft, msc_all), \", \", lua_true_map_keys(msc_cs, msc_all), \", \", lua_true_map_keys(msc_if, msc_fo), \", \", lua_str_list(msc_pl), \", \", lua_str_map_keys(msc_pt, msc_pl), \")\"]))", "            list mflds = s[fields]", "            for mf0 in mflds:", "                dict mfn2 = mf0", "                emit_line(st, cat([\"krt.model_set_value(\", lua_str(mn2), \", \", lua_str(mfn2[name]), \", \", emit_expr(st, mfn2[expr]), \")\"]))", "            dict mcons2 = msc[ctor]", "            list mcps = mcons2[params]", "            list mcpl = [\"self\"]", "            for mcp0 in mcps:", "                dict mcp = mcp0", "                mcpl.add(mcp[lua])", "            emit_line(st, cat([\"krt.model_construct(\", lua_str(mn2), \", function(\", mcpl.join(\", \"), \")\"]))", "            st.add(\"indent\", st[indent] + 1)", "            str msv = st[current_ret]", "            st.add(\"current_ret\", \"NONE\")", "            list mcbody = mcons2[body]", "            emit_hoist(st, collect_scope(mcbody))", "            emit_stmts(st, mcbody)", "            st.add(\"current_ret\", msv)", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end)\")", "            list mmorder = msc[method_order]", "            for mmn2 in mmorder:", "                dict msmeth6 = msc[methods]", "                dict mmi2 = msmeth6.take(mmn2)", "                list mmps = [ \"self\" ]", "                list mmpl = mmi2[params]", "                for mmp0 in mmpl:", "                    dict mmp = mmp0", "                    mmps.add(mmp[lua])", "                emit_line(st, cat([\"krt.model_method(\", lua_str(mn2), \", \", lua_str(mmn2), \", function(\", mmps.join(\", \"), \")\"]))", "                st.add(\"indent\", st[indent] + 1)", "                str msv2 = st[current_ret]", "                st.add(\"current_ret\", mmi2[ret])", "                list mmbody = mmi2[body]", "                emit_hoist(st, collect_scope(mmbody))", "                emit_stmts(st, mmbody)", "                st.add(\"current_ret\", msv2)", "                bool mmend = FALSE", "                if len(mmbody) > 0:", "                    dict mmlast = mmbody[len(mmbody) - 1]", "                    if mmlast[k] == \"return\":", "                        mmend = TRUE", "                if NOT mmend:", "                    emit_line(st, \"return krt.NONE\")", "                st.add(\"indent\", st[indent] - 1)", "                emit_line(st, \"end)\")", "        elif sk == \"self_init\":", "            list sfl = s[fields]", "            for sf0 in sfl:", "                dict sf = sf0", "                emit_line(st, cat([\"krt.model_create_field(self, \", lua_str(sf[name]), \", \", sf[lua], \", \", \"false\", \", \", lua_str(sf[type]), \")\"]))", "        elif sk == \"field_create\":", "            dict fce = s[expr]", "            str fcx = checked(emit_expr(st, fce), fce[t], e_nullable(fce), s[type])", "            str fcb = emit_expr(st, s[base])", "            str fcc = \"false\"", "            if is_const_name(s[name]):", "                fcc = \"true\"", "            emit_line(st, cat([\"krt.model_create_field(\", fcb, \", \", lua_str(s[name]), \", \", fcx, \", \", fcc, \", \", lua_str(s[type]), \")\"]))", "        elif sk == \"field_assign\":", "            dict fae = s[expr]", "            str fax = checked(emit_expr(st, fae), fae[t], e_nullable(fae), s[type])", "            emit_line(st, cat([\"krt.model_set(\", emit_expr(st, s[base]), \", \", lua_str(s[name]), \", \", fax, \")\"]))", "        elif sk == \"decl\":", "            dict de = s[expr]", "            str dx = checked(emit_expr(st, de), de[t], e_nullable(de), s[type])", "            if de[t] != \"NONE\":", "                dx = typed_wrap(dx, s[type])", "            emit_line(st, cat([s[lua], \" = \", dx]))", "        elif sk == \"assign\":", "            dict ae = s[expr]", "            str ax = checked(emit_expr(st, ae), ae[t], e_nullable(ae), s[type])", "            if ae[t] != \"NONE\":", "                ax = typed_wrap(ax, s[type])", "            emit_line(st, cat([s[lua], \" = \", ax]))", "        elif sk == \"compound\":", "            dict ce = s[expr]", "            str lhs = wrap_flint(s[lua], \"flint\", s[nullable])", "            str rhs = wrap_flint(emit_expr(st, ce), ce[t], e_nullable(ce))", "            str cop = s[op]", "            str ex = \"\"", "            if cop == \"+\":", "                ex = cat([\"(\", lhs, \" + \", rhs, \")\"])", "            elif cop == \"-\":", "                ex = cat([\"(\", lhs, \" - \", rhs, \")\"])", "            elif cop == \"*\":", "                ex = cat([\"(\", lhs, \" * \", rhs, \")\"])", "            elif cop == \"/\":", "                ex = cat([\"krt.div(\", lhs, \", \", rhs, \")\"])", "            elif cop == \"//\":", "                ex = cat([\"krt.idiv(\", lhs, \", \", rhs, \")\"])", "            elif cop == \"%\":", "                ex = cat([\"krt.mod(\", lhs, \", \", rhs, \")\"])", "            else:", "                ex = cat([\"krt.pow(\", lhs, \", \", rhs, \")\"])", "            emit_line(st, cat([s[lua], \" = \", ex]))", "        elif sk == \"setindex\":", "            dict tg = s[target]", "            dict tv = s[expr]", "            str tvx = emit_expr(st, tv)", "            if tg[k] == \"dget\":", "                dict tb = tg[base]", "                str tdx = wrap_dict(emit_expr(st, tb), tb[t], e_nullable(tb))", "                emit_line(st, cat([\"krt.dict_set(\", tdx, \", \", lua_str(tg[key]), \", \", tvx, \")\"]))", "            else:", "                dict tib = tg[base]", "                dict tii = tg[index]", "                str tbx = emit_expr(st, tib)", "                str tix = wrap_flint(emit_expr(st, tii), tii[t], e_nullable(tii))", "                str tibb = base_type(tib[t])", "                if tibb == \"list\" OR tibb == \"froz\":", "                    str tbx2 = \"\"", "                    if tibb == \"froz\":", "                        tbx2 = wrap_froz(tbx, tib[t], e_nullable(tib))", "                    else:", "                        tbx2 = wrap_list(tbx, tib[t], e_nullable(tib))", "                    emit_line(st, cat([\"krt.list_replace(\", tbx2, \", \", tix, \", \", tvx, \")\"]))", "                else:", "                    emit_line(st, cat([\"krt.index_set(\", tbx, \", \", tix, \", \", tvx, \")\"]))", "        elif sk == \"panic\":", "            emit_line(st, cat([\"krt.fail(\", lua_str(s[cat]), \", \", lua_str(s[msg]), \")\"]))", "        elif sk == \"exprstmt\":", "            emit_line(st, emit_expr(st, s[expr]))", "        elif sk == \"if\":", "            list brs = s[branches]", "            flint bi = 0", "            while bi < len(brs):", "                dict br = brs[bi]", "                dict bc = br[cond]", "                str kw = \"elseif\"", "                if bi == 0:", "                    kw = \"if\"", "                emit_line(st, cat([kw, \" krt.truthy_strict(\", emit_expr(st, bc), \") then\"]))", "                st.add(\"indent\", st[indent] + 1)", "                emit_stmts(st, br[body])", "                st.add(\"indent\", st[indent] - 1)", "                bi += 1", "            if s.contains(\"else_body\"):", "                emit_line(st, \"else\")", "                st.add(\"indent\", st[indent] + 1)", "                emit_stmts(st, s[else_body])", "                st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "        elif sk == \"try\":", "            st.add(\"try_id\", st[try_id] + 1)", "            str tid = str(st[try_id])", "            str tnorm = cat([\"__try_normal_\", tid])", "            str tok2 = cat([\"__try_ok_\", tid])", "            str tval2 = cat([\"__try_val_\", tid])", "            str terr2 = cat([\"__try_err_\", tid])", "            str thok = cat([\"__try_hok_\", tid])", "            str hval2 = cat([\"__try_hval_\", tid])", "            str thandled = cat([\"__try_handled_\", tid])", "            emit_line(st, \"do\")", "            st.add(\"indent\", st[indent] + 1)", "            emit_line(st, cat([\"local \", tnorm, \" = \\{\\}\"]))", "            emit_line(st, cat([\"local \", tok2, \", \", tval2]))", "            emit_line(st, cat([tok2, \", \", tval2, \" = pcall(function()\"]))", "            st.add(\"indent\", st[indent] + 1)", "            emit_stmts(st, s[body])", "            emit_line(st, cat([\"return \", tnorm]))", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end)\")", "            emit_line(st, cat([\"if not \", tok2, \" then\"]))", "            st.add(\"