not \", tok2, \" then _G.error(\", tval2, \", 0) end\"]))", "            emit_line(st, cat([\"if \", tval2, \" ~= \", tnorm, \" then return \", tval2, \" end\"]))", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "        elif sk == \"while\":", "            st.add(\"loop_id\", st[loop_id] + 1)", "            str lid = str(st[loop_id])", "            str cont = cat([\"__continue_\", lid])", "            str brk = cat([\"__break_\", lid])", "            dict wc2 = s[cond]", "            emit_line(st, cat([\"while krt.truthy_strict(\", emit_expr(st, wc2), \") do\"]))", "            st.add(\"indent\", st[indent] + 1)", "            list ls = st[loop_stack]", "            ls.add({cont: cont, brk: brk})", "            emit_stmts(st, s[body])", "            emit_line(st, cat([\"::\", cont, \"::\"]))", "            ls.del(len(ls) - 1)", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "            emit_line(st, cat([\"::\", brk, \"::\"]))", "        elif sk == \"break\":", "            list lsb = st[loop_stack]", "            dict topb = lsb[len(lsb) - 1]", "            emit_line(st, cat([\"goto \", topb[brk]]))", "        elif sk == \"continue\":", "            list lsc = st[loop_stack]", "            dict topc = lsc[len(lsc) - 1]", "            emit_line(st, cat([\"goto \", topc[cont]]))", "        elif sk == \"for\":", "            st.add(\"loop_id\", st[loop_id] + 1)", "            str fid = str(st[loop_id])", "            str fcont = cat([\"__continue_\", fid])", "            str fbrk = cat([\"__break_\", fid])", "            str fv = s[lua]", "            str fto = cat([\"__to_\", fid])", "            emit_line(st, \"do\")", "            st.add(\"indent\", st[indent] + 1)", "            str form = s[form]", "            if form == \"upto\":", "                emit_line(st, cat([\"local \", fv, \" = 0\"]))", "                dict fte = s[to]", "                emit_line(st, cat([\"local \",